import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAR: [CaseTemplate] = [hardwareShoplift, mailboxBaseball, ballgamePistol, streetRaceWreck, laptopCarBreakin, exTrespassPorch, phoneKnockedAway, tillShortage, roommateCreditCard, checkFromGrandma, checkpointDwi, coachShoveRef, exPostingCampaign, formerEmployeeFiles, plannedPharmacyRobbery, toddlerLeftHome, partyGrab, roadRageBat, fourthDwi, debtKidnapping]

    static let hardwareShoplift = SmallCases.make(
        key: "story.hardwareShoplift",
        category: .property,
        headlines: ["Man Walks Out of Hardware Store With Power Drill Under Jacket", "Loss Prevention Stops Shopper at the Door"],
        law: "larcenyMerchant",
        spec: "Took a power drill valued at $189 from {V}, a hardware store, without paying, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A loss prevention officer watched {D} slip a boxed drill under a jacket in the tool aisle on {DATE} and walk past the registers. The officer stopped {DL} at the door. {DL} says {D.he} meant to pay and forgot the drill was under the jacket. The loss was put at $189.",
        state: [E(.video, 3, "Aisle Camera", "{D} puts a boxed drill under a jacket."), E(.physical, 2, "Drill", "The unopened drill with the store's tag, recovered at the door.", .search)],
        defense: [E(.statement, 1, "Forgot", "{DL} says {D.he} forgot it was under the jacket.")],
        role: "Loss prevention officer",
        exam: [.direct("What is your job at the store?", "\"I'm a loss prevention officer. I watch the floor and the cameras for theft, and I make stops when I see merchandise leave without payment.\""), .direct("What did you see on {DATE}?", "\"At 2:10 p.m. {D} entered the tool aisle. At 2:14 I saw {DL} take a boxed drill off the shelf and put it under a jacket.\""), .direct("What did you do?", "\"I followed at a distance and watched {DL} pass the registers without stopping. I made the stop at the front door at 2:20.\""), .direct("What was the drill worth?", "\"$189. It was an unopened, boxed drill with the store's tag, and I recovered it from under the jacket at the door.\""), .direct("How did {D} react?", "\"{D.He} looked surprised and said, I forgot it was there. I asked {D.him} to come back inside, and {D.he} came along.\""), .direct("What does the aisle camera show?", "\"The drill going under the jacket and {D.he} looking up the aisle once before walking on. It's clear footage.\""), .cross("Isn't it true the defendant did stop at a register?", "\"I recall {D.he} buying a small item for about $4. I'm not sure whether the drill was visible at that moment.\""), .cross("Was the jacket open or closed?", "\"It was unzipped when {D.he} came in. I can see in the video the box was held under it with an arm.\""), .cross("Did {D} try to run when you stopped {D}?", "\"No. {D.He} stood still, answered my questions, and walked back inside without trouble.\""), .cross("How far is the register from the door?", "\"About twenty feet. {D.He} had passed the register and was a few steps from the exit when I stopped {D.him}.\""), .cross("Did the defendant say anything about intending to pay?", "\"{DL} said it was an oversight. I can't say whether that's true, and I didn't see {DL} reach for a wallet at the door.\"")],
        theory: ("{D} hid a drill and walked out.", "A forgotten item."),
        allocution: "\"I came in for a few small parts for a repair, and I picked up a drill and tucked it under my jacket to free my hands. I got distracted and walked toward the door without thinking. I had the money in my wallet, and I meant to pay. I'm sorry to the store, and I'm sorry for the scene it caused.\"",
        truths: ("{DL} bought a $4 item at the register with the drill still hidden.", "The jacket had been unzipped when {DL} entered."),
        defendant: [.direct("Why did you go to the tool aisle?", "\"I needed a few small parts for a repair. I picked up a drill because I'd been thinking about getting one.\""), .direct("How did the drill end up under your jacket?", "\"I tucked it there to free my hands while I looked at other things. I got distracted by my phone and forgot about it.\""), .direct("Did you intend to pay for it?", "\"Yes. I meant to buy it, and I had the money in my wallet. I just lost track of it.\""), .direct("What did you buy at the register?", "\"A small item that cost about $4. I was thinking about my phone and my errand list when I paid.\""), .direct("What did you say to the officer at the door?", "\"That I forgot it was there, and that I'd pay for it. I said it right away, and I walked back in without arguing.\""), .direct("Have you been in trouble for theft before?", "\"No. I've never been charged with shoplifting, and I've shopped in that store for years.\""), .cross("You slid a $189 drill under your jacket, didn't you?", "\"Yes. It's what the video shows. I tucked it under my arm so I could carry other things.\""), .cross("You walked past the registers with it?", "\"I went to a register for a small item and then moved on. I wasn't thinking about the drill.\""), .cross("Isn't it odd to forget a boxed drill under your arm?", "\"I understand why it looks that way. I was distracted, and it was not a heavy box.\""), .cross("You looked up the aisle before walking away, didn't you?", "\"I was looking for a part. I wasn't checking for staff, and I wasn't aware of anyone watching me.\""), .cross("You never took the drill out to pay?", "\"No, because I forgot. If I'd meant to steal, I'd have hurried out instead of buying a $4 item.\"")],
        openings: ("At 2:14 p.m. the aisle camera shows {D} lifting a boxed $189 drill and putting it under a jacket. {DL} then walked past the registers toward the door, where a loss prevention officer made the stop.", "{D} was distracted, tucked the drill under an arm to free both hands, and bought a small item while still carrying it. The defense says a forgotten item is not larceny."),
        closings: ("The camera shows the drill going under the jacket, the walk past the registers, and the stop at the door. A shopper does not forget a boxed drill for six minutes while walking through a store.", "{D} bought another item at a register while carrying the drill in plain view of the cashier, and said right away it was an oversight. The State has to prove intent, and a distracted shopper is not a thief."),
        timeline: [(0, "2:10 p.m.: {DL} enters the tool aisle."), (0, "2:14 p.m.: the drill goes under the jacket."), (0, "2:20 p.m.: {DL} is stopped at the door.")],
        identified: "An aisle camera.",
        impact: "This happens every week. A tool like that drill gets tucked under a jacket, and our loss prevention officer has to chase it down. It costs us the merchandise, the time, and the nerves of the staff. We're a small hardware store, and the shrink is what makes the difference.",
        genders: ["D": .male])

    static let mailboxBaseball = SmallCases.make(
        key: "story.mailboxBaseball",
        category: .property,
        headlines: ["Teens Seen Swinging Bat at Mailboxes on Quiet Road", "Six Mailboxes Smashed in One Night"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a mailbox, causing damage of $420, on {DATE}.",
        ages: 18...24,
        victim: true,
        summary: "Six mailboxes along a rural road were smashed overnight on {DATE}. A resident's porch camera showed a car slow at each box and a passenger swing a bat. The car belongs to {D}. {DL} says {D.he} lent the car to a friend that night. Damage was put at $420.",
        state: [E(.video, 3, "Porch Camera", "A passenger swings a bat at a mailbox from a slow car."), E(.document, 3, "Registration", "The car is registered to {D}.")],
        defense: [E(.statement, 1, "Lent the Car", "{DL} says a friend had the car.")],
        role: "Resident",
        exam: [.direct("What did you see on your porch camera?", "\"Overnight, a car slowed at each of the six mailboxes along our road, and someone in the passenger seat swung a bat out the window at every one.\""), .direct("What damage did you find in the morning?", "\"All six boxes along the road were smashed, some knocked off their posts. The damage was put at about $420 across the neighbors.\""), .direct("Whose car is it?", "\"The deputy traced the plate on the car to {D}. The make and color match what my camera recorded.\""), .direct("Where do you live in relation to the road where the boxes were smashed?", "\"About a quarter mile from the first box. My porch looks toward the road and the camera covers the front of the house and about sixty feet of the shoulder.\""), .direct("Describe how the car moved on the video.", "\"It rolled slowly along the shoulder, stopped at each mailbox, and a passenger leaned out of the window and swung a bat. Then it moved on to the next one.\""), .direct("What was the damage, and what did it cost to repair?", "\"All six boxes were in the ditch, three of them still on their posts. The total was about $420, and mine was the one nearest the road.\""), .cross("You can't see anyone's face on the video, can you?", "\"No. It was dark, and the figures are shadows. I can tell you about the car and the bat, but not who held it.\""), .cross("Isn't it possible the car was lent to someone else?", "\"It's possible. I only know the car, not who was in it. I have no way to say who was behind the wheel.\""), .cross("Did you see the car come or go yourself?", "\"No. I was asleep. I found out about it from the camera footage the next morning.\""), .cross("Could you read the license plate on the video?", "\"Partly. A deputy enhanced it and traced the car, but at the time I couldn't read it myself.\""), .cross("Did you ever see the people in the car in person?", "\"No. I was asleep until the noise woke me, and by the time I got to the window the car was gone.\"")],
        theory: ("{D} smashed mailboxes with a bat.", "A borrowed car."),
        allocution: "\"I was home in bed by eleven that night, and I did not swing a bat at anyone's mailbox. A friend borrowed my car earlier in the evening, and I did not ask where it was going. The bat lives in my trunk with my softball glove. I'm sorry that six families woke to smashed boxes, and I hope the right person is found.\"",
        truths: ("A bat with splintered paint was in {DL}'s trunk.", "A neighbor saw {DL}'s car in the driveway all night."),
        defendant: [.direct("Were you in that car that night?", "\"No. I was not in the car and I did not swing a bat at anybody's mailbox. I was at home.\""), .direct("Who had the car that night?", "\"A friend borrowed it. I handed over the keys earlier in the evening and did not ask where it was headed.\""), .direct("Why was a bat in your trunk?", "\"I play softball, and the bat lives in the trunk with my glove. It's been there for months.\""), .direct("Where were you that night?", "\"At home. I was in bed by eleven and I didn't leave the house until the next morning.\""), .direct("When did you lend the car, and to whom?", "\"Around nine that evening, to a friend who needed to pick someone up. I left the keys on the table and went to bed.\""), .direct("What did the deputies ask you when they came to your home?", "\"They asked about my car and where I was the night before. I told them a friend had borrowed it and that I was in bed by eleven.\""), .cross("A bat with splintered paint was in your trunk. How do you explain that?", "\"I can't explain the paint. Bats get chipped. I did not use it on any mailbox, and I do not know how it got splintered.\""), .cross("Can you name the friend who borrowed your car?", "\"I can give a name, but I understand it does not look great that I cannot produce the person right now.\""), .cross("Your car is on the camera at six mailboxes. Doesn't that point to you?", "\"It points to my car, not to me. I did not see the footage until deputies showed me.\""), .cross("You say a friend had the car. Did you ask where it went?", "\"No. I trusted my friend and didn't ask, and I didn't check the car when it was brought back.\""), .cross("The car was back in your driveway by morning with no one to confirm who drove it. Isn't that convenient?", "\"It looks that way. I can't prove who had the car, but I know I wasn't in it.\"")],
        openings: ("Six mailboxes along a rural road were smashed overnight. A porch camera shows a car slowing at each one while a passenger swings a bat, and the car belongs to {D}.", "The camera shows a car and a bat but no faces. The defense will show that {D} lent the car to a friend and was never at those mailboxes."),
        closings: ("Six mailboxes, six swings, and one car on camera that belongs to {D}, with a bat in its trunk. This is not a coincidence, and the car did not drive itself.", "The video shows a car and a shadow, not {D}. A friend had the keys, and the State has not proved otherwise. A bat in a trunk of a softball player is not evidence of vandalism."),
        timeline: [(0, "11:50 p.m.: the first mailbox is smashed."), (1, "12:05 a.m.: the sixth mailbox is smashed."), (1, "{V} finds the boxes in the ditch.")],
        identified: "A porch camera and the registration.",
        mood: .indifferent,
        impact: "They cost us a week of mail. Six boxes were smashed along our road overnight, and the postal service held everything until we replaced them. Neighbors drove to town for medications and bills. Out here it's more than inconvenience. We're a long way from anything.")

    static let ballgamePistol = SmallCases.make(
        key: "story.ballgamePistol",
        category: .publicOrder,
        headlines: ["Fan's Pistol Spotted in Waistband at Youth Ballgame", "Deputy Finds Loaded Handgun at Concession Stand"],
        law: "concealedWeapon",
        spec: "Carried a concealed pistol on or about {D.his} person, on {DATE}.",
        ages: 21...60,
        victim: false,
        summary: "A parent told a deputy at a youth ballgame on {DATE} that {D} had a gun under {D.his} shirt. A deputy found a loaded pistol in {DL}'s waistband. {DL} says {D.he} thought {D.his} permit covered it and the shirt had ridden up.",
        state: [E(.physical, 3, "Pistol", "A loaded pistol in {D}'s waistband.", .search), E(.statement, 2, "Parent", "The parent saw the grip when {D} reached for a drink.")],
        defense: [E(.statement, 1, "Permit", "{DL} says {D.he} believed {D.his} permit covered it.")],
        role: "Sheriff's deputy",
        exam: [.direct("What call brought you to the ballgame?", "\"A parent told me at a youth ballgame on {DATE} that a spectator had a gun under a shirt. I walked over to the stands to find {D}.\""), .direct("What did the parent say?", "\"That the parent saw the grip when {D.he} reached for a drink and the shirt rode up. The parent said it looked like a pistol.\""), .direct("What did you do when you reached {D}?", "\"I asked {D.him} to step aside, away from the children, and asked if {D.he} was carrying. {D.He} said yes.\""), .direct("What did you find?", "\"A loaded pistol in {D.his} waistband. I removed it, cleared it, and secured it in my vehicle.\""), .direct("What did your check show about the defendant's permit?", "\"The permit had expired about three months earlier. {D.He} was not licensed to carry on that date.\""), .direct("What did the defendant say?", "\"{D.He} said {D.he} thought the permit still covered it and that the shirt had ridden up by accident.\""), .cross("Isn't it true the defendant told you right away about the pistol?", "\"Yes. When I asked, {D.he} answered honestly and handed it over without any argument.\""), .cross("Did the defendant display or touch the weapon?", "\"No. It stayed in the waistband the whole time. The parent only saw the grip when the shirt shifted.\""), .cross("Did the defendant say anything about renewing the permit?", "\"{D.He} said {D.he} had renewed online and was waiting for a card. I saw no renewal on file when I checked, though a pending submission may not show.\""), .cross("Were there any threats or incidents at the game?", "\"None. {D.He} was sitting in the stands watching a game, and no one reported any trouble.\""), .cross("Did the defendant cooperate fully?", "\"Yes. {D.He} was polite, answered my questions, and apologized. It was a calm contact.\"")],
        theory: ("{D} carried a concealed pistol without a valid permit.", "A mistake about a permit."),
        allocution: "\"I carry a pistol everywhere, and I've held a permit for years. I submitted my renewal online and thought I was covered while it processed, and the old one had expired first. I reached for a drink and my shirt rode up. I'm sorry to the parent who was alarmed. I'll make sure my paperwork is current.\"",
        truths: ("The permit expired three months earlier.", "{DL} had renewed online but never received a card."),
        defendant: [.direct("Why were you carrying a pistol at the game?", "\"I carry it everywhere. I've had a permit for years, and I carried that day the same way I always have.\""), .direct("What did you believe about your permit?", "\"That it was still good. I'd submitted my renewal online and thought I was covered while waiting for the card.\""), .direct("When did you submit the renewal?", "\"About two weeks after it expired, I think. I didn't realize the old one expired first, and I hadn't looked at the date.\""), .direct("How did the grip become visible?", "\"I reached for a drink and my shirt rode up. I didn't mean to show it, and I felt terrible when the deputy approached.\""), .direct("What did you do when the deputy asked?", "\"I told the truth and handed it over. I didn't want any trouble near children.\""), .direct("What would you do differently?", "\"I'd check my permit date and leave the gun at home until I had the new card in hand.\""), .cross("Your permit expired three months before that day, didn't it?", "\"I'm told so. I didn't know it, and I know that I should have checked the date myself.\""), .cross("You never received a renewal card?", "\"No. I submitted online and never got anything in the mail. I didn't follow up, and that was my mistake.\""), .cross("You carried a loaded pistol among children?", "\"Yes. It was holstered under my shirt, but I know that it's a place where people are sensitive about guns.\""), .cross("You didn't look at the expiration date on the old card?", "\"No. I'd carried it so long I stopped paying attention. I know a careful person would have looked.\""), .cross("You didn't call the sheriff to check if the renewal went through?", "\"I didn't. In hindsight, yes. I assumed it was fine.\"")],
        openings: ("At a youth ballgame, a parent saw a pistol grip under {D}'s shirt and told a deputy, who found a loaded pistol in {DL}'s waistband. The State will show the concealed handgun permit expired about three months earlier.", "{D} believed the permit still covered it, had submitted a renewal online, and told the deputy the truth on the spot. The defense says a mistake about paperwork is not the knowing violation the law requires."),
        closings: ("A loaded pistol at a children's game, a permit that expired ninety-five days earlier, and no valid card in hand. Carrying concealed without a current permit is what the statute forbids.", "{D} renewed online, expected a card in the mail, and was candid with the deputy. A lapse in paperwork that {D.he} never noticed is not a willful carrying of a concealed weapon."),
        timeline: [(-95, "{DL}'s permit expires."), (-80, "{DL} submits a renewal online."), (0, "A parent sees the grip."), (0, "A deputy takes the pistol.")],
        identified: "A parent's tip and a deputy's search.",
        mood: .divided,
        doctrines: ["burdenOfProof", "mistakeOfFact"],
        genders: ["D": .male])

    static let streetRaceWreck = SmallCases.make(
        key: "story.streetRaceWreck",
        category: .traffic,
        headlines: ["Two Cars Race on County Road, One Ends in Cornfield", "Reckless Driving Charged After Late-Night Race"],
        law: "recklessDriving",
        spec: "Drove a motor vehicle on a highway carelessly and heedlessly in willful disregard of the rights and safety of others, on {DATE}.",
        ages: 18...30,
        victim: false,
        summary: "Two cars raced down a county road at midnight on {DATE}. One lost control and ended in a cornfield. Neither driver was seriously hurt. A passenger told a trooper {D} was in the other car and was going over 90. {DL} says {D.he} was only driving fast to get home.",
        state: [E(.statement, 3, "Passenger", "{D} raced the other car, over 90 mph."), E(.document, 2, "Trooper Report", "Tire marks and debris for half a mile.")],
        defense: [E(.statement, 1, "Heading Home", "{DL} says {D.he} was just trying to get home.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("What happened on the county road that night?", "\"At midnight, two cars raced down the county road. One lost control and ended up in a cornfield. Neither driver was seriously hurt.\""), .direct("What did the passenger tell you?", "\"The passenger said {D} was in the other car, that the two cars were racing, and that {DL} was going over 90 miles an hour.\""), .direct("Did you find the other car?", "\"The passenger described it and I located the drivers afterward. I did not have radar on the road that night.\""), .direct("Where was the wreck, and what did you find at the scene?", "\"On a straight stretch of county road with a cornfield on the right. I found a sedan on its side in the first rows of corn and tire marks along the pavement for about half a mile.\""), .direct("What did the debris tell you?", "\"Pieces of a bumper and a side mirror were scattered along the shoulder, with fresh gouges where a car had left the road. It fit a car that lost control at high speed.\""), .direct("How did you speak with the passenger?", "\"At the scene, away from the car. The passenger was shaken but coherent and said two cars lined up and took off, and that {DL} was in the other one going over 90.\""), .cross("The passenger was riding in the car that crashed, correct?", "\"Yes. The passenger was in the other car, so the passenger has a stake in how this is described.\""), .cross("You have no radar or video of {D}'s speed, do you?", "\"No. I have no radar reading and no video of the race. I have the passenger's account and the crash scene.\""), .cross("Does the passenger have any dispute with the defendant?", "\"I heard that later, yes, there may be some history. I did not know it when I took the statement.\""), .cross("Did you check the defendant's car for damage?", "\"I did when I located it. There was no damage that suggested contact with the crashed car.\""), .cross("Did you see the defendant's car on the road?", "\"No. I only know it from the passenger's description and from where I found it later.\"")],
        theory: ("{D} raced on a county road.", "A driver heading home."),
        allocution: "\"I was not racing anyone. I was driving fast because I wanted to get home, and I know that is no excuse. I did not look at the speedometer, and I'm sorry if I went over ninety. I'm glad nobody was seriously hurt. I'll slow down on those back roads.\"",
        truths: ("{DL} had posted a video of the road earlier that evening.", "The passenger had a grudge against {DL}."),
        defendant: [.direct("Were you racing another car?", "\"No. I was not racing anyone. I was driving fast because I wanted to get home, and that is all.\""), .direct("How fast were you going?", "\"Fast, but not racing. I did not look at the speedometer, and I do not think I was going 90.\""), .direct("What about the video you posted that evening?", "\"It was a short video of the road. It was just scenery, and I did not post it to show a race.\""), .direct("Where were you coming from that night?", "\"A friend's house about twenty minutes away. I'd stayed later than planned and was trying to get home before midnight.\""), .direct("What road were you on, and was anyone with you?", "\"The same county road, by myself. I was heading home and didn't pass or race another car that I remember.\""), .direct("What did you do when you heard about the wreck?", "\"I was shocked. I went to the trooper the next day and told what I knew, and I offered to hand over my phone.\""), .cross("The passenger says you were over 90. Why would the passenger say that?", "\"I do not know. We had some history, and maybe that is why. I cannot read the passenger's mind.\""), .cross("You admit you were driving fast on a dark county road at midnight, don't you?", "\"Yes. It was not smart. I was tired and wanted to be home, and I did not think it was dangerous.\""), .cross("You posted a video of that road earlier that night. Wasn't that a preview?", "\"No. It was just the road. I post things like that all the time, and it did not mean anything.\""), .cross("The passenger told the trooper you were going over 90. Why would anyone make that up?", "\"I don't know. We'd had a falling out, and I think it's easy to point at someone when you're scared.\""), .cross("You posted a video of the road earlier that evening. Is that a coincidence?", "\"It's a road I drive every day. The video is a short clip of the scenery.\"")],
        openings: ("At midnight, two cars raced down a county road, and one ended up in a cornfield. A passenger tells deputies that {D} was in the other car, going over 90 miles an hour.", "There was no radar, no video, and a passenger with a grudge. The defense will show that {D} was driving fast to get home, not racing anyone."),
        closings: ("A passenger saw two cars racing and put {D} in one of them at over 90. A wreck in a cornfield is the proof that this was not just fast driving.", "The State's only witness was in the other car, had a grudge, and offers no radar or video. Driving fast is not the same as racing, and doubt remains."),
        timeline: [(0, "11:50 p.m.: two cars line up at a stop sign."), (0, "11:58 p.m.: one loses control."), (1, "12:20 a.m.: a trooper arrives.")],
        identified: "A passenger's account.",
        mood: .indifferent)

    static let laptopCarBreakin = SmallCases.make(
        key: "story.laptopCarBreakin",
        category: .property,
        headlines: ["Laptop Taken From Locked Car at Trailhead", "Window Smashed, Bag Gone"],
        law: "breakingVehicle",
        spec: "Broke or entered a motor vehicle of {V} with intent to commit larceny therein, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "{V} parked at a trailhead on {DATE} and returned to a smashed window and a missing laptop bag. A trail camera showed {D} walking from the lot with the bag 40 minutes later. {DL} says {D.he} found the bag on the trail.",
        state: [E(.video, 3, "Trail Camera", "{D} walks from the lot with a laptop bag."), E(.physical, 3, "Laptop Bag", "{V}'s bag, found in {D}'s apartment.", .search)],
        defense: [E(.statement, 1, "Found It", "{DL} says {D.he} found the bag on the trail.")],
        role: "Car owner",
        exam: [.direct("What did you find when you came back to your car?", "\"The window was smashed, glass was all over the seat, and my laptop bag was gone. I had been on the trail for about an hour.\""), .direct("What was in the bag?", "\"My laptop and some papers. It was a work laptop, so I lost more than the machine.\""), .direct("What did the trail camera show?", "\"It shows {D} walking from the lot with my bag, about forty minutes after I parked.\""), .direct("Where did you park and for how long?", "\"At the trailhead lot around nine in the morning. I planned to be gone four or five hours on a loop, and the lot was nearly empty.\""), .direct("Was anything else disturbed in the car?", "\"The glove box was open and my registration was on the floor. Nothing else looked touched.\""), .direct("How did you learn who took the bag?", "\"A deputy checked the trail camera at the head of the path. It shows {DL} walking out of the lot at about noon carrying a bag like mine.\""), .cross("{D} says the bag was found on the trail. Did you find that?", "\"No, I did not. My bag was in my car when I parked. I never took it on the trail.\""), .cross("Was there glass in the bag when you got it back?", "\"Some, yes. There was glass in it, which fits with it coming from the car.\""), .cross("Did you see anyone near the car when you left?", "\"Only one other vehicle, an older pickup, parked at the far end. I didn't see who it belonged to.\""), .cross("Did you recover the laptop, and in what condition?", "\"Yes, it was handed to deputies and returned to me. It had a cracked corner and a bit of glass in the case.\""), .cross("Did you see the defendant break your window?", "\"No. I was hiking the whole time. I only know the window was smashed when I returned and that {D.he} walked out of the lot with my bag on camera.\""), .cross("The glass on the defendant's shoes came from the lot, didn't it?", "\"I was told the glass matched broken bottles in the lot, not my window. I cannot say where it came from, only what the analyst reported.\"")],
        theory: ("{D} smashed a window and took a bag.", "A found bag."),
        allocution: "\"I have never broken into a car in my life. I was hiking a short loop with my dog, and I found that bag on the trail and picked it up because I did not want it left in the weather. I meant to find a name inside and turn it in. I'm sorry for {V}'s broken window and the loss of the laptop.\"",
        truths: ("There was glass on {DL}'s shoes.", "The glass on {DL}'s shoes matched broken bottles in the lot, not the car window."),
        defendant: [.direct("Did you smash that window?", "\"No. I did not break anyone's car window. I have never broken into a car in my life.\""), .direct("Where did you get the bag?", "\"I found it on the trail. It was sitting off to the side, and I picked it up because it looked like someone dropped it.\""), .direct("What did you plan to do with it?", "\"I planned to turn it in. I took it to my apartment and intended to look for a name inside.\""), .direct("Walk us through what you were doing at the trailhead.", "\"Hiking a short loop with my dog. I was there for about two hours and was heading back to my car when I saw the bag.\""), .direct("Where exactly was the bag?", "\"On the trail about a quarter mile from the lot, set against a log. It had a few leaves on it and looked like it had been there a while.\""), .direct("What did you do with it?", "\"I carried it back toward the lot. I planned to take it to the sheriff's office on the way home, and I put it in my car.\""), .cross("There was glass on your shoes, wasn't there?", "\"Yes, but it was from the parking lot. That lot has broken bottles everywhere, and I walked across it.\""), .cross("If you meant to turn in the bag, why take it home?", "\"It was getting dark and I was tired. I figured I would take it to the sheriff in the morning.\""), .cross("The camera shows you walking out of the lot with it. How is that the trail?", "\"I came back through the lot after I found it. I was heading to my car, and I know it looks bad.\""), .cross("The camera shows you carrying the bag out of the lot, not toward the ranger office. Why?", "\"The ranger station was closed, and I thought the sheriff's office was the right place. I should have left it with someone right there.\""), .cross("You didn't look inside the bag to find an owner?", "\"I looked for a tag on the outside and didn't find one. I didn't open it because it felt wrong going through someone's things.\"")],
        openings: ("{V} came back from a trail hike to a smashed window and a missing laptop bag. A trail camera shows {D} walking from the lot with that bag forty minutes later.", "{D} found a bag on the trail and meant to turn it in. The defense will show that nothing ties {DL} to a broken window."),
        closings: ("A smashed window, a stolen bag, and a camera showing {D} carrying it away, with glass on {D.his} shoes. The bag did not walk off the trail on its own.", "The glass on {D}'s shoes came from a lot full of broken bottles. A found bag and an honest plan to return it are not larceny. The State has no one who saw a window break."),
        timeline: [(0, "9 a.m.: {V} parks and hikes."), (0, "11:20 a.m.: the window is smashed."), (0, "12 p.m.: {DL} leaves the lot with the bag."), (0, "2 p.m.: {V} returns.")],
        identified: "A trail camera.",
        impact: "My whole work life was on it. I'm a freelancer, and that laptop held two years of client files, drafts, and invoices. I came back from a trail to a smashed window and an empty seat. I lost weeks of income, and I'm still rebuilding what I can.")

    static let exTrespassPorch = SmallCases.make(
        key: "story.exTrespassPorch",
        category: .family,
        headlines: ["Ex-Boyfriend Keeps Returning to Woman's Porch After Being Told to Leave", "Neighbor Records Man Pacing at Door"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V} after being notified not to, on {DATE}.",
        ages: 20...50,
        victim: true,
        summary: "{V} told {D} in writing in the spring not to come to {V.his} home. On {DATE}, {DL} stood on the porch for 40 minutes, knocking and calling {V.his} name. A neighbor recorded part of it. {DL} says {D.he} was dropping off {V.his} mail.",
        state: [E(.video, 3, "Neighbor Video", "{D} knocks and calls {V}'s name on the porch."), E(.document, 3, "No-Trespass Notice", "A written notice delivered to {D}.")],
        defense: [E(.statement, 1, "Mail", "{DL} says {D.he} came to deliver mail.")],
        role: "Homeowner",
        exam: [.direct("What happened in the spring?", "\"I gave {D} a written notice telling {DL} not to come to my home. I delivered it so there was no doubt about what I wanted.\""), .direct("Why did you do that?", "\"We'd had a falling out and {D.he} kept coming around. I wanted it to stop, and I thought writing it down would be clear.\""), .direct("What happened on {DATE}?", "\"At about 6:10 p.m. {D.He} came to my porch and began knocking and calling my name. I didn't open the door.\""), .direct("How long did it go on?", "\"About forty minutes. {D.He} knocked, called out, and walked around the porch, and I called deputies at about 6:50.\""), .direct("How did you feel?", "\"Scared and angry. I'd told {D.him} to stay away in writing, and I was inside with the lights off waiting for deputies.\""), .direct("Was any of it recorded?", "\"A neighbor recorded part of it on a phone. It shows {DL} knocking and calling my name on the porch.\""), .cross("Isn't it true {D} had mail with {D}'s name on it?", "\"I've been told there was an envelope. I never saw it myself, because I didn't open the door.\""), .cross("Did the defendant threaten you?", "\"No. {DL} knocked and called my name. I didn't hear a threat, and I didn't see {DL} try the door.\""), .cross("Were you in contact with the defendant after the notice?", "\"There were a few messages about returning property. I never invited {D.him} to knock on my door, and I wanted it handled another way.\""), .cross("Did you tell the defendant to stop before calling deputies?", "\"No. I didn't open the door or answer. I called deputies after forty minutes of it.\""), .cross("Did the defendant leave when deputies arrived?", "\"{DL} was still on the porch when they pulled up and didn't argue with them.\"")],
        theory: ("{D} returned after being told not to.", "A man dropping off mail."),
        allocution: "\"I was dropping off mail that came to my address for {V}, and I wanted to hand it over directly because it had personal information. I remembered the written notice, but I thought this was a limited errand, and I should have mailed it. I'm sorry that I frightened {V.him} by standing on that porch.\"",
        truths: ("The envelope had been opened and was addressed to {DL}.", "{V}'s own text two days earlier invited {DL} to pick up a box from the porch."),
        defendant: [.direct("Why did you go to {V}'s porch?", "\"I was dropping off mail that came to my address for {V}. I thought I'd leave it on the porch.\""), .direct("Why were you knocking?", "\"I wanted to hand it over directly. I didn't want it left in view, since it had personal information on it.\""), .direct("Did you know about the written notice?", "\"Yes. I remembered it, but I thought this was a limited errand, and I didn't think about it carefully.\""), .direct("Why did you call out {V}'s name?", "\"I thought {V} might be home and not hear the knock. I'd have left right away if {V} came to the door.\""), .direct("How long were you there?", "\"It felt like a few minutes, though I'm told forty. I may have waited longer than I realized, hoping to hand it over.\""), .direct("What did you do when the deputies arrived?", "\"I stayed where I was and told them about the mail. I showed them the envelope.\""), .cross("You knew {V} had told you in writing to stay away?", "\"I did. I received the notice, and I know what it said.\""), .cross("You stayed on the porch for forty minutes?", "\"I know it was a long time. I didn't count minutes, and I was frustrated that nobody answered.\""), .cross("You could have mailed the envelope or left it at the box, couldn't you?", "\"Yes, either would have worked. I didn't think about it at the time, and I'm sorry.\""), .cross("The envelope had been opened, hadn't it?", "\"It had been opened, and it was addressed to me. I'm not sure why, and I know it doesn't look like I was just delivering.\""), .cross("Did {V} ever invite you to pick something up from the porch?", "\"There was a text a couple of days before about a box. I thought that meant I could come by, and I may have misread it.\"")],
        openings: ("In the spring {V} handed {D} a written notice not to come to {V}'s home. On {DATE}, {DL} stood on the porch for 40 minutes, knocking and calling {V}'s name, and a neighbor recorded part of it.", "{D} says {D.he} came only to drop off {V}'s mail and had been invited to the porch by a text days earlier. The defense says that is a misunderstanding, not a knowing trespass."),
        closings: ("A written notice, forty minutes of knocking, and a neighbor's video of the whole thing. {D} knew the rule and came anyway, and {V} was terrified inside.", "{V}'s own text had invited {D} to the porch, and the envelope was addressed to {DL}. A person acting on that invitation did not knowingly trespass, and the State cannot prove otherwise."),
        timeline: [(-120, "{V} delivers the written notice."), (0, "6:10 p.m.: {DL} arrives on the porch."), (0, "6:50 p.m.: deputies are called.")],
        identified: "A neighbor's video.",
        mood: .wantsConviction,
        impact: "I want to feel safe at home. I told {D.him} in writing not to come here, and then I heard knocking on my porch for forty minutes. I stayed inside with the lights off and called a neighbor. I put a camera on the door and I think twice before I open it.",
        genders: ["D": .male, "V": .female])

    static let phoneKnockedAway = SmallCases.make(
        key: "story.phoneKnockedAway",
        category: .publicOrder,
        headlines: ["Man Knocks Phone From Woman's Hand During 911 Call", "Dispatcher Hears Struggle, Line Goes Dead"],
        law: "interferingEmergency",
        spec: "Willfully interfered with {V}'s communication with a 911 operator, on {DATE}.",
        ages: 19...55,
        victim: true,
        summary: "A dispatcher heard {V} say her address, a shout, and a crash before the line went dead on {DATE}. Deputies found {V}'s phone cracked across the room. {D}, {V}'s housemate, said {V} dropped it. {DL} says {D.he} never touched it.",
        state: [E(.digital, 3, "911 Recording", "A shout and a crash, then silence."), E(.physical, 2, "Phone", "A phone with a cracked screen across the room.")],
        defense: [E(.statement, 1, "Dropped", "{DL} says {V} dropped the phone.")],
        role: "911 dispatcher",
        exam: [.direct("What did you hear on the 911 call?", "\"A voice gave an address, then there was a shout, then a crash, and the line went dead.\""), .direct("Whose voice was shouting?", "\"A male voice. I could not make out every word, but it was a different voice from the one who gave the address.\""), .direct("What did deputies report?", "\"They found {V}'s phone cracked on the far side of the room, away from where it was likely to have fallen.\""), .direct("What do you do as a dispatcher, and what did the call look like?", "\"I answer 911 and send help. This call came in at 9:05 p.m. and showed an address and a mobile number.\""), .direct("Describe the sounds on the recording.", "\"A voice gave the address clearly, then there was a shout from another voice, and then a loud noise like something hitting a hard surface. The line went silent after that.\""), .direct("What did you do after the line went dead?", "\"I called back twice and got no answer. I dispatched deputies to the address and kept trying until they reported they were on scene.\""), .cross("Can you say whether that voice was {D}'s?", "\"No. I can't identify a voice from one shout. I can only say it was male and angry.\""), .cross("A phone can simply be dropped, can't it?", "\"Yes, phones fall all the time. I cannot tell you from audio alone whether this one was dropped or thrown.\""), .cross("Did the crash sound like a phone falling?", "\"It was a loud crash, but it could have been the phone hitting a hard floor. I cannot be certain.\""), .cross("Can you tell where the shouting came from relative to the phone?", "\"Not precisely. The shout was closer to the phone than the caller's voice had been, but I can't give a distance.\""), .cross("Did you hear any words in the shout?", "\"A few. I couldn't make out all of it, and I can't say with certainty what the words were or who said them.\"")],
        theory: ("{D} knocked a phone away during a 911 call.", "A dropped phone."),
        allocution: "\"I did not touch that phone. {V} was on a call, and it fell, and I came in from the kitchen when I heard shouting. I'm sorry for the fright of that night and for the crash that made it so loud. I would never stop anyone from calling for help.\"",
        truths: ("The male voice said 'give me that.'", "A neighbor heard the phone fall and {V} cry out before any shouting."),
        defendant: [.direct("Did you take {V}'s phone?", "\"No. I did not touch the phone. I never grabbed it from {V.him} or knocked it away.\""), .direct("What happened that night?", "\"{V} was on the phone and it fell. There was a lot of noise, and I came in from another room.\""), .direct("Did you shout?", "\"Someone shouted. It might have been me asking what happened. I was surprised, and I raised my voice.\""), .direct("Walk us through what you were doing at 9 p.m. that night.", "\"I was in the kitchen making dinner. I heard {V} on the phone in the living room, and then I heard a thump.\""), .direct("What did you see when you came into the room?", "\"{V} was standing by the couch looking at the phone on the floor. It was cracked, and {V} looked upset.\""), .direct("Did you say anything?", "\"I asked what happened and if {V} was all right. My voice was raised because I was startled, and I think that's what's on the recording.\""), .cross("The voice on the recording said 'give me that.' Was that you?", "\"I did not say that. It must have been someone else, or I do not remember it.\""), .cross("There was a bruise on {V}. How did that happen?", "\"I think it came from moving furniture. I did not hurt {V.him}.\""), .cross("You were the only other person in the home, weren't you?", "\"Yes, as best I can tell. But I did not take the phone, and I did not do anything to {V.him}.\""), .cross("You were the only other person in the house. Who else could it have been?", "\"I don't know. It could be a voice from a TV or someone outside, or I'm misremembering what I said in the moment.\""), .cross("A neighbor heard the phone fall before any shouting, didn't the neighbor?", "\"So I am told. I was in my room and heard a bang, and I came out after. I cannot say what order things happened in.\""), .cross("You were upset with {V} that night, weren't you?", "\"We had argued earlier about the rent. I was frustrated, but I did not take the phone or lay a hand on {V}.\"")],
        openings: ("A 911 dispatcher heard an address, a shout, and a crash before the line went dead. Deputies found {V}'s phone cracked across the room, and {V}'s housemate, {D}, was the only other person there.", "By the end of this trial, the proof will show that a phone can fall and that a shout on a recording does not identify {D}. The State has a sound, not a person."),
        closings: ("An address, a male voice shouting, a crash, and a dead line. The phone was across the room and {D} was the only one there. That is not a coincidence.", "A dispatcher cannot say whose voice it was, and phones fall. The State is asking you to turn a sound into a certainty, and it has not done that."),
        timeline: [(0, "9:05 p.m.: {V} dials 911."), (0, "9:06 p.m.: the line goes dead."), (0, "9:20 p.m.: deputies arrive.")],
        identified: "A 911 recording.",
        mood: .wantsConviction,
        impact: "I couldn't get help. I was trying to give the dispatcher my address when the phone flew out of my hand and the line went dead. I stood in the hallway shaking until deputies arrived. I keep a second phone hidden in a drawer now.",
        genders: ["D": .male, "V": .female])

    static let tillShortage = SmallCases.make(
        key: "story.tillShortage",
        category: .whiteCollar,
        headlines: ["Gas Station Clerk Accused of Pocketing Till Cash", "Owner Counts $1,800 Short Over Three Weeks"],
        law: "embezzlement",
        threshold: 6,
        spec: "Embezzled $1,800 entrusted to {D} by {V}, a gas station owner, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "{V}'s gas station till was short every night {D} closed over three weeks ending {DATE}, for $1,800 total. A register camera showed {DL} taking bills from the drawer after the last customer. {DL} says {D.he} was paying for supplies {V} asked {D.him} to buy.",
        state: [E(.video, 3, "Register Camera", "{D} removes bills after the last customer on four nights."), E(.document, 3, "Till Reports", "Short $1,800 on {D}'s closing nights.")],
        defense: [E(.statement, 1, "Supplies", "{DL} says {V} had {D.him} buy supplies from the till.")],
        role: "Gas station owner",
        exam: [.direct("How much was missing from your till?", "\"Over three weeks, it came to $1,800 short. The shortages came on the nights {D} closed the station.\""), .direct("What does the register camera show?", "\"After the last customer, {DL} takes bills from the drawer. It happened on multiple nights, and it was never put into the deposit.\""), .direct("Did you ask {D} to buy supplies?", "\"On occasion I asked for supplies, but I always expected receipts. Not one receipt was turned in for those weeks.\""), .direct("How do you count the till at closing?", "\"The closing clerk prints a report from the register, counts the drawer, and drops the deposit in the safe. I review the report the next morning.\""), .direct("When did you first notice a shortage?", "\"About three weeks before the date of the report. The first couple of shortages were small, and then they came every night one particular clerk closed.\""), .direct("What did you do about it?", "\"I installed a camera over the register. It shows {DL} taking bills from the drawer after the last customer on four nights.\""), .cross("{D} says the cash was spent on supplies. Could that be true?", "\"If it were, there would be receipts and a log. There was neither, so I cannot confirm it.\""), .cross("Other clerks closed the station too, didn't they?", "\"They did. The shortages followed {D.his} shifts, not the others'. I compared the nights.\""), .cross("Did you ask {D} to keep a log?", "\"I did, and I do not think {D.he} kept one. I never saw it.\""), .cross("Did you tell the defendant in advance that supplies would be bought from the till?", "\"Occasionally, for small things like cleaning products, but not for anything near these amounts.\""), .cross("Do you keep receipts for supplies bought from the till?", "\"I ask for them. I didn't get any from {D.him}, but I hadn't set a system for it either.\"")],
        theory: ("{D} took from the till.", "Supplies bought on the owner's order."),
        allocution: "\"I took cash from that drawer for supplies the owner asked me to buy, cleaning products and light bulbs, and I was not stealing. I put the receipts in my pocket and lost them, which I know was careless. I'm sorry for the shortage and the doubt it caused. I covered many shifts during those weeks, and I'd welcome a full accounting.\"",
        truths: ("{DL} had not turned in a single receipt.", "{V} had told {DL} to keep a log, which {DL} did not."),
        defendant: [.direct("Did you take money from the till?", "\"I took cash for supplies the owner asked me to buy. I was not stealing. I thought I would be reimbursed.\""), .direct("Where are the receipts?", "\"I lost them. I put them in my pocket, and they did not make it back to the office. I know that sounds bad.\""), .direct("Why did you close so many nights?", "\"It was a busy few weeks. I covered a lot of shifts, and I was the one on the schedule.\""), .direct("What supplies did you buy for the station?", "\"Cleaning products, light bulbs, and a case of oil for the pumps. The owner sent me out with cash from the drawer for each trip.\""), .direct("How did you keep track of what you spent?", "\"I put the receipts in my jacket pocket and meant to bring them in. When I got home they were in the laundry and some of them got ruined.\""), .direct("Did the owner ever ask for the receipts?", "\"Not until the owner noticed the till was short. By then I couldn't find most of them.\""), .cross("You took money on four different nights, didn't you?", "\"Yes, because supplies were needed in several trips. I was keeping the business going.\""), .cross("$1,800 in supplies and no receipts. How do you explain that?", "\"I cannot explain it any better than I have. I should have kept the paper.\""), .cross("The owner told you to keep a log. Did you?", "\"No. I was busy. I should have, and I'm so sorry.\""), .cross("$1,800 over three weeks is a lot of oil and light bulbs. What else did you buy?", "\"Some of it was supplies, and some of it went to things for the station I thought the owner wanted. I know I should have kept better records.\""), .cross("The camera shows you taking bills on four different nights. Why take cash after the last customer?", "\"That was when the drawer was counted and I knew what was needed for the next morning. I wasn't hiding it.\"")],
        openings: ("For three weeks, a gas station till came up short every night {D} closed, a total of $1,800. A register camera shows {DL} taking bills from the drawer after the last customer.", "The defense will present evidence that {D} was asked to buy supplies and spent the cash on them. The State has shortages and a camera, not an intent to steal."),
        closings: ("Eighteen hundred dollars, four closing nights, and a camera showing bills leaving the drawer. {D} had no receipts and no log to back up a story about supplies.", "A busy station, a worker who covered shifts, and supplies bought with cash. Lost receipts are careless, not criminal. The State must prove intent, and it hasn't."),
        timeline: [(-21, "The first short night."), (-7, "{V} installs a register camera."), (0, "The fourth night on video."), (1, "{V} counts the total.")],
        identified: "A register camera.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "I can't afford this. Eighteen hundred dollars went missing in three weeks from a station that barely turns a profit. I trusted my closer with the keys and the drawer. Now I'm covering nights myself and I'm exhausted.")

    static let roommateCreditCard = SmallCases.make(
        key: "story.roommateCreditCard",
        category: .cyber,
        headlines: ["Roommate's Credit Card in His Name Runs Up $6,000", "Mail Pile Reveals Card Opened With Stolen Information"],
        law: "identityTheft",
        threshold: 6,
        spec: "Knowingly obtained and used the identifying information of {V} to obtain credit, on {DATE}.",
        ages: 19...40,
        victim: true,
        summary: "{V} learned on {DATE} that a credit card in {V.his} name carried $6,000 in charges. The card was mailed to the shared apartment. {V}'s roommate {D} was seen taking the envelope from the mail pile. {DL} says {V} agreed to co-sign the card.",
        state: [E(.document, 3, "Application", "An online application in {V}'s name, using {D}'s phone number."), E(.document, 2, "Statements", "$6,000 in charges at stores near {D}'s work.")],
        defense: [E(.statement, 1, "Co-Sign", "{DL} says {V} agreed to co-sign the card.")],
        role: "Roommate",
        exam: [.direct("Did you agree to a credit card in your name?", "\"Never. I did not agree to anything, and I never signed an application or told anyone to open one for me.\""), .direct("What happened when you found out?", "\"I learned that a card in my name carried $6,000 in charges. The phone number on the account was {D}'s.\""), .direct("How did {D} come into this?", "\"The card was mailed to our shared apartment, and {D.he} was seen taking the envelope from the mail pile.\""), .direct("How did you discover the card?", "\"I got a call from a credit bureau alert saying a new account had been opened in my name. When I looked it up, there was a card with $6,000 in charges and a billing address at our apartment.\""), .direct("What kinds of purchases were on the statements?", "\"Mostly stores near where {D.he} works: electronics, clothing, and a few gift cards. None of them were places I shop.\""), .direct("How was the card mailed to the apartment?", "\"It came in a plain envelope with my name on it. We share a mailbox and a pile on the counter, and {D.he} was the one who picked it up.\""), .cross("You and the defendant shared a mailbox, didn't you?", "\"Yes, we shared one. Anyone could pick up the mail, but {DL} was the one seen taking that envelope.\""), .cross("You trusted the defendant, didn't you?", "\"We were roommates and I gave {DL} access to some things. I did not expect this.\""), .cross("Did you ever text the defendant something about a card?", "\"I don't recall that. If there is a text, I would like to see it.\""), .cross("Did you ever say yes, even jokingly, to the defendant using your information?", "\"No. {D.He} asked about co-signing once and I said I wasn't comfortable with it. I never said anything that sounded like permission.\""), .cross("How can you be sure the application wasn't filled out by someone else?", "\"The application used {D.his} phone number for the verification call. I can't say who typed it, but that number points to {D.him}.\"")],
        theory: ("{D} opened a card in a roommate's name.", "A co-signed card."),
        allocution: "\"{V} agreed to co-sign that card, and we talked about it in our kitchen. There's nothing in writing, and I should have asked for something signed. Most of the charges were groceries and household things for the apartment we shared. I'm sorry for the misunderstanding and for the trouble it caused {V}.\"",
        truths: ("The application used {V}'s Social Security number from a lease.", "A text from {V} said 'fine, use my info for the card, I'll cover it.'"),
        defendant: [.direct("Did you open that credit card?", "\"I did, with {V}'s okay. We talked about it and {V} agreed to co-sign, so I thought it was approved.\""), .direct("Is there a signature from {V}?", "\"No. There is nothing signed. It was a conversation, and we left it at that.\""), .direct("What did you charge on the card?", "\"Groceries and some household things. Most of it was for the apartment we shared.\""), .direct("Walk us through how you and {V} came to share an apartment.", "\"We met through a roommate listing and had lived together about a year. We split rent and groceries and got along fine most of the time.\""), .direct("When did the conversation about the card happen?", "\"A few weeks before the card arrived. I said my credit was bad and asked if I could use {V}'s info for a card to rebuild it, and {V} said fine and that I should cover the bills.\""), .direct("What happened when the bill came?", "\"{V} saw the amount and changed {V.his} mind. I told {V.him} I would pay it off, and I started making payments before anyone called deputies.\""), .cross("{V} says it never happened. Why should the jury believe you?", "\"Because it did. {V} changed {V.his} mind after seeing the bill, and I understand why.\""), .cross("$6,000 on groceries?", "\"Over some months, it adds up. I used it for the house, not for myself alone.\""), .cross("You took the envelope without telling {V}. Why?", "\"I thought it was mine. The card was supposed to be for both of us, so I picked it up.\""), .cross("You have nothing in writing from {V}. Why didn't you ask for anything?", "\"We were roommates and trusted each other. I didn't think a conversation needed a signature, and I know now that it did.\""), .cross("Six thousand dollars is far more than groceries and household items. What was it for?", "\"Some of it was household items, and some was things I wanted. I told myself I would repay it, and I lost track of how much I was spending.\"")],
        openings: ("A credit card in {V}'s name ran up $6,000 in charges. It was mailed to the shared apartment, {V}'s roommate {D} was seen taking the envelope, and {V} never agreed to any of it.", "The defense witnesses will explain that {V} agreed to co-sign and that {D} used the card for shared household costs. This is a roommate dispute, not identity theft."),
        closings: ("A card {V} never applied for, mailed to a shared apartment, taken by {D}, and $6,000 in charges. {V}'s information was used without any real permission.", "A roommate said yes, then changed {V.his} mind when the bill came. The State cannot show there was no permission to start, and that matters."),
        timeline: [(-60, "{DL} asks {V} to co-sign; {V} refuses."), (-45, "The application is filed online."), (0, "{V} sees the statement."), (1, "{V} files a report.")],
        identified: "The application and statements.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        genders: ["V": .male])

    static let checkFromGrandma = SmallCases.make(
        key: "story.checkFromGrandma",
        category: .whiteCollar,
        headlines: ["Grandson Cashes Check Made Out to Cash", "Bank Teller Notes Shaky Signature"],
        law: "uttering",
        spec: "Offered a forged check for $900 to a bank, knowing it to be forged, on {DATE}.",
        ages: 19...35,
        victim: true,
        summary: "A bank teller took a $900 check on {DATE} from {D} that bore {V}'s signature. {V}, {DL}'s grandmother, told the bank she never signed it. {DL} says {V} signed it and has forgotten.",
        state: [E(.document, 3, "Check", "A check for $900 with an unlike signature."), E(.statement, 3, "Teller", "{D} presented the check and cashed it.")],
        defense: [E(.statement, 1, "Forgotten", "{DL} says {V} signed it and has forgotten.")],
        role: "Grandmother",
        exam: [.direct("How are you related to {D}?", "\"{D} is my grandchild. I raised {D.him} part of the time when {D.he} was small, and we've always been close, which is why this hurts.\""), .direct("What happened with the check?", "\"The bank called me to say a check for $900 had been cashed on my account with my signature. I told them I never signed it.\""), .direct("When had the defendant last been to your house?", "\"About a week before, on a visit. {D.He} sat with me at the kitchen table, where I keep the checkbook in a drawer.\""), .direct("How do you sign your checks?", "\"The same way for decades, with a slanted capital and a long tail on the last letter. The signature on that check doesn't look like mine.\""), .direct("What did you do after hearing from the bank?", "\"I reviewed my statement two days later, found the check, and told the bank I hadn't written it. They had me look at the image.\""), .direct("Did you give the defendant any money recently?", "\"Not that I recall. I've given gifts at birthdays, but nothing like $900, and I'd remember writing a check that large.\""), .cross("Isn't it true your memory isn't as sharp as it was?", "\"I forget names now and then, but I know what I sign. A check for $900 is a big matter for me.\""), .cross("Did you ever give the defendant money by check before?", "\"Yes, small amounts, a birthday check or help with a bill. I never wrote one without telling someone.\""), .cross("Did you see the signature on the check yourself?", "\"Yes, the bank showed me the image. I told them it was not mine, and I'd say that again today.\""), .cross("Could you have signed it and forgotten?", "\"I've asked myself that. I don't think so, because I'd remember a check that large, and the writing looks wrong to me.\""), .cross("Did you tell the defendant you were upset?", "\"I haven't spoken to {DL} much since. I wanted the bank to sort it out first, and I didn't want a shouting match.\"")],
        theory: ("{D} forged a signature and cashed a check.", "A forgotten gift."),
        allocution: "\"My grandmother and I were very close, and I visited every week to help with groceries and the yard. During one visit, {V} signed that check for nine hundred dollars and said it was a gift to help me with rent. I'm sorry that {V.he} doesn't remember. I never wanted to hurt my grandmother.\"",
        truths: ("{DL} had been in the kitchen where the checkbook was kept.", "A handwriting examiner saw an unlike hand."),
        defendant: [.direct("What was your relationship with your grandparent?", "\"Very close. I visited every week or two, and I helped with groceries and the yard. We've been like friends my whole life.\""), .direct("Did you get a check from {V}?", "\"Yes. During a visit {V} signed a check for $900 and said it was a gift to help with my rent. I took it to the bank.\""), .direct("Why did you cash it at the bank?", "\"That's where the check was drawn, and I needed the money for rent that week. I presented my ID and cashed it.\""), .direct("Did you sign {V}'s name?", "\"No. {V} signed it at the kitchen table in front of me. I would never forge a signature on my own grandparent's check.\""), .direct("Why does {V} say the signature isn't {V.his}?", "\"I think {V} has forgotten. Memory isn't what it was, and I know that's hard to say about someone I love.\""), .direct("How are you coping with what happened?", "\"Sick. I don't want to fight with {V}, and I'd pay the $900 back if it keeps the family together.\""), .cross("You were in the kitchen where the checkbook was kept?", "\"Yes, we sat at the table and the checkbook is in a nearby drawer. I knew where it was, as any grandchild would.\""), .cross("A handwriting examiner said the signature was in an unlike hand?", "\"I'm told so. I can only say I watched {V} sign it, and I can't explain what the examiner saw.\""), .cross("You didn't mention the gift to anyone else in the family?", "\"No. It was between us, and I didn't think it needed to be announced.\""), .cross("You needed rent money that week, didn't you?", "\"I did. I was behind, and that's why the gift mattered so much to me.\""), .cross("Did you ask {V} for a receipt or note?", "\"No. A grandparent's gift doesn't come with paperwork, and I trusted that it was fine.\"")],
        openings: ("A bank teller cashed a $900 check on {V}'s account that bore {V}'s signature, and {V} says {V.he} never signed it. {D} is {V}'s own grandchild, was in the kitchen a week earlier where the checkbook is kept, and presented the check at the counter.", "{V} signed that check as a gift at the kitchen table, and {D} cashed it openly with an ID. The defense says a grandparent who has forgotten a gift is not proof of forgery."),
        closings: ("The signature has a slant and a tail that {V} has used for decades, and the examiner saw an unlike hand. {D} had the opportunity and the need, and the check ended up in {DL}'s hands.", "{D} cashed the check at the counter with a real ID and in front of a teller. The State has asked a jury to choose between a loving grandchild and a forgotten gift, and doubt remains."),
        timeline: [(-7, "{DL} visits {V}."), (0, "{DL} cashes the check."), (2, "{V} reviews her statement.")],
        identified: "A teller and a handwriting exam.",
        mood: .divided,
        genders: ["V": .female])

    static let checkpointDwi = SmallCases.make(
        key: "story.checkpointDwi",
        category: .traffic,
        headlines: ["Driver Blows 0.10 at Sobriety Checkpoint", "Checkpoint Stop Ends in DWI Arrest"],
        law: "dwi",
        spec: "Operated a motor vehicle on a street while subject to an impairing substance, on {DATE}.",
        ages: 21...60,
        victim: false,
        summary: "A deputy at a sobriety checkpoint smelled alcohol on {D} at 11:30 p.m. on {DATE}. {D.He} blew 0.10 on a breath test an hour later. {DL} says {D.he} had two beers with dinner and the machine was wrong.",
        state: [E(.forensic, 3, "Breath Test", "A 0.10 on an instrument at the jail."), E(.statement, 2, "Deputy", "Odor of alcohol, glassy eyes, slow speech.")],
        defense: [E(.statement, 1, "Two Beers", "{DL} says {D.he} had two beers.")],
        role: "Sheriff's deputy",
        exam: [.direct("Where were you working on {DATE}?", "\"I was part of a sobriety checkpoint on a county road. We stopped each car in line and looked for signs of impairment.\""), .direct("What did you notice about {D}?", "\"At 11:30 p.m. I noticed a smell of alcohol when {D} rolled the window down. {D.his} eyes were glassy and speech was slow.\""), .direct("What did you do next?", "\"I asked {D.him} to pull aside and did a short interview and field checks. I decided there was enough to arrest for impaired driving.\""), .direct("What did the defendant say about drinking?", "\"{D.He} said two beers with dinner. {D.He} said dinner started around 7, and that was the only drinking.\""), .direct("What did the breath test show?", "\"A 0.10 at the jail around 12:30 a.m., about an hour after the stop. The instrument is the one we use for every arrest.\""), .direct("Who ran the test?", "\"A certified operator at the jail who followed the standard observation period. I watched {D.him} in the room during the wait.\""), .cross("Isn't it true the breath test was an hour after the stop?", "\"Yes, it was 12:30. That's the normal time to get an arrestee processed and tested.\""), .cross("Did {D} drive erratically before you stopped {D}?", "\"No. It was a checkpoint, so every car was stopped. I had no report of weaving or speeding for {D.his} car.\""), .cross("Did the defendant fall or stumble during the checks?", "\"Not that I recall. {D.He} was steady on {D.his} feet, though slow in speech and with glassy eyes.\""), .cross("Was the instrument maintained?", "\"I believe it's calibrated regularly. I'm not the technician and I can't speak to its monthly check records.\""), .cross("Did the defendant refuse any test?", "\"No. {D.He} agreed to every test and was cooperative with me and the operator.\"")],
        theory: ("{D} drove drunk.", "Two beers."),
        allocution: "\"I had two beers with dinner at a restaurant near the interstate, and I felt fine. I wasn't tired or unsteady, and I had no idea there was a checkpoint until I came upon it. I don't believe the machine's reading was right. I'm sorry for the inconvenience to the deputies, and I'll be more careful about even a single drink.\"",
        truths: ("{DL} had three drink receipts that evening.", "The instrument had failed its monthly check two weeks earlier, a technician said."),
        defendant: [.direct("What did you drink that evening?", "\"Two beers with dinner. We ate around 7, and I didn't have anything after that. I'd have stopped at two to be safe.\""), .direct("Where did you eat?", "\"At a restaurant near the interstate. I took a couple of hours over dinner, and then I drove toward home.\""), .direct("How did you feel when you reached the checkpoint?", "\"Fine. I wasn't tired or unsteady. I had no idea there was a checkpoint ahead until I saw the lights.\""), .direct("What did you tell the deputy?", "\"That I had two beers with dinner. I said it right away and I didn't try to hide the smell.\""), .direct("What did you think of the breath result?", "\"I was shocked. I don't think two beers could get me to a 0.10, and I believe the machine was wrong.\""), .direct("Did you cooperate?", "\"Completely. I did every test they asked, blew into the machine, and sat quietly in the room.\""), .cross("You smelled of alcohol at the window, didn't you?", "\"I'd had a couple of beers earlier, so I wasn't surprised if the deputy smelled it. I didn't deny it.\""), .cross("Your eyes were glassy and your speech slow?", "\"It was late and I was tired. I know the deputy wrote that, but I felt fine.\""), .cross("You had receipts for more than two drinks that night, didn't you?", "\"The tab had a few items on it. I'd say two beers, and if there was a third it was small, and I didn't think it mattered.\""), .cross("You blew a 0.10, over the limit?", "\"That's what the machine says. I don't think it's right, but I know that's the number on the paper.\""), .cross("You can't prove the machine was wrong?", "\"I can't personally. I'm told it had trouble with a check a couple of weeks before, but I'm not a technician.\"")],
        openings: ("At 11:30 p.m. at a sobriety checkpoint, a deputy smelled alcohol on {D}, saw glassy eyes and slow speech, and arrested {DL}. A breath test an hour later registered 0.10.", "{D} had two beers with dinner and cooperated fully. The defense says the machine that produced that number had failed a check two weeks earlier, and a failing instrument cannot support a conviction."),
        closings: ("Alcohol on the breath, glassy eyes, slow speech, and a 0.10 an hour later all point one way. {D} drove after drinking, and the evidence shows it at the checkpoint and at the jail.", "Two beers with dinner and a machine with a recent failed check. The State relies on a single number from an instrument that was not working properly, and that leaves reasonable doubt."),
        timeline: [(0, "7 p.m.: dinner and drinks."), (0, "11:30 p.m.: the checkpoint stop."), (1, "12:30 a.m.: the breath test.")],
        identified: "A checkpoint stop.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let coachShoveRef = SmallCases.make(
        key: "story.coachShoveRef",
        category: .violent,
        headlines: ["Coach Shoves Youth League Referee After Call", "Parents Film Altercation at Rec Center"],
        law: "simpleAssault",
        spec: "Assaulted {V}, a youth-league referee, by shoving {V.him}, on {DATE}.",
        ages: 28...55,
        victim: true,
        summary: "After a disputed call at a youth game on {DATE}, {D}, a team coach, walked onto the court and shoved {V}, the referee, into a bench. A parent filmed it. {DL} says {V} was in {D.his} face and {D.he} pushed to create space.",
        state: [E(.video, 3, "Parent Video", "{D} shoves {V} into a bench."), E(.statement, 2, "Scorekeeper", "{D} walked onto the court and pushed {V}.")],
        defense: [E(.statement, 1, "Space", "{DL} says {V} was in {D.his} face.")],
        role: "Referee",
        exam: [.direct("What were you doing at the game on {DATE}?", "\"I was refereeing a youth game. I've done it for years, and I enjoy it. I blew the whistle on a close call around 4:10.\""), .direct("What happened after that call?", "\"{D}, a coach, objected loudly. Then {D.he} walked onto the court and came toward me, shouting about the call.\""), .direct("What did {D} do?", "\"At about 4:12, {D.he} shoved me hard in the chest, and I went back into a bench. I was bruised and shaken.\""), .direct("How did the children react?", "\"They stopped playing and stared. A few of them looked scared, and some parents shouted at {DL} to stop.\""), .direct("Who recorded it?", "\"A parent filmed it on a phone. A scorekeeper also saw {DL} walk onto the court and push me.\""), .direct("What did you do afterward?", "\"I ended the game and asked the league official to call deputies. They arrived and took reports from me and the witnesses by 4:30.\""), .cross("Isn't it true the defendant was upset about the call?", "\"Yes, {D.he} was angry. I don't deny it was a close call and that I could understand the frustration.\""), .cross("Did the defendant hit you with a fist or a closed hand?", "\"No. It was an open-handed shove to the chest. I wasn't struck in the face and didn't lose consciousness.\""), .cross("Were you backing away when the defendant came at you?", "\"I took a step back as {DL} approached. I did not touch {DL}, and I was trying to keep distance.\""), .cross("Was the defendant warned by the league before?", "\"I know {D.he} had been warned a couple of times. I can't say what those warnings said.\""), .cross("Did you ask the defendant to leave the court?", "\"I told {D.him} to return to the bench. {D.He} kept coming, and then the shove happened.\"")],
        theory: ("{D} shoved a referee.", "A push to make space."),
        allocution: "\"I disagreed with a call and walked out to ask the referee about it, and I got more upset as we talked. I pushed to create space, and I'm ashamed. There were kids watching, and I let them down. I'm sorry to {V}, and I'll step back from coaching until I can show them better.\"",
        truths: ("{DL} had been warned by the league twice.", "The video shows {V} backing away."),
        defendant: [.direct("What happened on the court that day?", "\"I disagreed with a call and walked out to ask the referee about it. I got more upset than I know I should have.\""), .direct("Why did you shove {V}?", "\"{V} was right in my face, and I felt crowded. I pushed to create some space. I didn't mean to knock {V} over.\""), .direct("How hard did you push?", "\"Not very, in my mind. I put my hands out and pushed, and I didn't realize {V} would go into the bench.\""), .direct("How has this affected you?", "\"Ashamed. There were kids watching, and I should have set a better example. I apologized to the league.\""), .direct("Have you coached before?", "\"Yes, for a few seasons. I've never had an incident like this, and I love working with the kids.\""), .direct("What would you do differently?", "\"I'd stay at the bench and talk to the league after the game. I let my temper take over.\""), .cross("The video shows you shoving {V} into a bench, doesn't it?", "\"It shows me pushing {V} and {V} going back. I'm not denying it, and I regret that.\""), .cross("The video shows {V} backing away, doesn't it?", "\"I'm told {V} stepped back, but I thought {V} was moving toward me. I was in the heat of it.\""), .cross("You walked onto the court uninvited?", "\"Yes. I wasn't supposed to be on the court, and I know it was wrong.\""), .cross("The league had warned you twice about your conduct?", "\"Yes, I'd received two warnings. They were about arguing, and I didn't think they meant this.\""), .cross("{V} was bruised?", "\"I understand there was bruising. I never wanted to hurt anyone, and I'd apologize in person.\"")],
        openings: ("After a disputed call at a youth game, {D}, a team coach, walked onto the court and shoved {V}, the referee, backward into a bench. A parent filmed it and a scorekeeper saw it, and the State will show the push was deliberate.", "{D} says {V} was in {D.his} face and the push was meant only to create space. The defense says the heat of a youth game does not turn a moment of anger into an intent to assault."),
        closings: ("The parent's video shows a coach walking onto the court, shoving a referee into a bench, and children looking on. {D} had been warned twice by the league, and this time there was a bruise.", "{V} was close, the call was disputed, and {D} reacted for a moment and then apologized. The State has a push, but not the intent to harm that the charge requires."),
        timeline: [(0, "4:10 p.m.: the disputed call."), (0, "4:12 p.m.: the shove."), (0, "4:30 p.m.: deputies take reports.")],
        identified: "A parent's video.",
        mood: .indifferent,
        impact: "I've reffed for twenty years. I've been yelled at plenty, but I've never been shoved into a bench in front of children. A parent filmed it, and I had to watch myself fall. I took two weeks off, and I'm not sure I want to go back to the gym.",
        genders: ["V": .male])

    static let exPostingCampaign = SmallCases.make(
        key: "story.exPostingCampaign",
        category: .cyber,
        headlines: ["Woman Says Ex Posted Dozens of Messages About Her Online", "Messages Continued After She Blocked Him"],
        law: "cyberstalking",
        spec: "Willfully harassed {V} by electronic communications, on {DATE}.",
        ages: 20...50,
        victim: true,
        summary: "After {V} ended the relationship, {D} posted more than 60 messages about {V} on social media over five weeks ending {DATE}, including {V}'s workplace and routines. {V} blocked {DL} twice. {DL} says the posts were venting and never named {V}.",
        state: [E(.digital, 3, "Posts", "More than 60 posts, many naming {V}'s workplace."), E(.digital, 2, "Block Records", "{V} blocked two accounts used by {D}.")],
        defense: [E(.statement, 1, "Venting", "{DL} says the posts were venting and never named {V}.")],
        role: "Victim",
        exam: [.direct("What was your relationship with {D}?", "\"We dated for several months. I ended it, and {D} did not take it well. The posts began about five days after we broke up.\""), .direct("What did the defendant post?", "\"More than 60 messages over five weeks. Many mentioned my workplace, my routines, and where I was likely to be.\""), .direct("How did you find out about the posts?", "\"Friends told me first. Then I saw them myself, and I took screenshots because I knew I would need them.\""), .direct("What did you do about it?", "\"I blocked the first account about ten days into it. New posts came from a second account, so I blocked that too.\""), .direct("How did the posts affect you?", "\"I was afraid to go to work. I changed my route and asked a coworker to walk me to my car.\""), .direct("When did you report it?", "\"At the end of the five weeks, on {DATE}. I took the screenshots and block records to a deputy.\""), .cross("Isn't it true the posts did not always name you?", "\"Some didn't use my name. But everyone who knew us knew who it was about, because they named my workplace and described my day.\""), .cross("Did the defendant ever contact you directly?", "\"Not after I blocked the first account. The posts were all public, and I never got a private threat.\""), .cross("Did you know the second account was the defendant's?", "\"I believed it was because of the style and the timing. I can't swear who typed it.\""), .cross("Did the defendant threaten you with violence?", "\"Not in so many words. The posts said where I'd be and when, and that frightened me.\""), .cross("Did you respond online?", "\"No. I didn't reply or post about {D.him}. I only blocked and saved everything.\"")],
        theory: ("{D} harassed an ex online.", "Venting."),
        allocution: "\"I was hurt and angry after the breakup, and I vented on social media to friends. I never used {V}'s name, and I thought I was writing about a situation. I see now that others could tell who it was, and I'm sorry. I'll take down every post and keep my feelings to myself.\"",
        truths: ("A post listed {V}'s car and parking spot.", "A mutual friend admitted posting from {DL}'s old account."),
        defendant: [.direct("Why did you post about {V}?", "\"I was hurt and angry after the breakup. I was venting to friends and thought I was posting on my own page.\""), .direct("Did you name {V} in the posts?", "\"No. I never used the name. I wrote about a person and a situation, and I thought that kept it general.\""), .direct("Why did you mention a workplace?", "\"I was complaining about how the breakup affected my life. I didn't intend it as a way to locate anyone.\""), .direct("Did you use a second account?", "\"I had an old account that I used for some of it. A mutual friend also had access to that account.\""), .direct("Did you intend to frighten {V}?", "\"No. I wanted to feel heard. I now see how it looked, and I'm sorry that {V} was afraid.\""), .direct("What have you done since?", "\"I deleted everything. I've stopped posting, and I'm trying to talk to someone about how I handle anger.\""), .cross("More than sixty posts in five weeks is a lot of venting, isn't it?", "\"It was too much. I let it spiral, and each post felt like it would help. It didn't.\""), .cross("{V} blocked you twice?", "\"I'm told so. After the first block I should have stopped, and instead I used another account.\""), .cross("You mentioned {V}'s car and parking spot in a post?", "\"One post did mention a car and a spot. I wasn't threatening anything, but I understand how it reads.\""), .cross("You knew {V} could see them?", "\"I knew mutual friends would. I thought it would stay among us, and I was wrong.\""), .cross("Did you ever ask {V}'s permission to post about the relationship?", "\"No. I didn't think about it that way. It was my story too, but I know it crossed a line.\"")],
        openings: ("After {V} ended a relationship, {D} posted more than 60 messages over five weeks, many naming {V}'s workplace and routines. {V} blocked two of {DL}'s accounts, and the State will show the posts were a campaign of harassment.", "{D} says these were angry vents after a hard breakup, written without naming {V}. The defense says the posts, however unwise, are not the true threats or stalking the State alleges."),
        closings: ("Sixty posts, two blocked accounts, and a workplace and car described for anyone to see. {V} changed routes and asked for an escort, and that is what harassment looks like.", "The posts never used {V}'s name, never threatened harm, and were venting from a hurt person. The State must show a pattern designed to terrorize, and a messy breakup does not meet that."),
        timeline: [(-35, "{V} ends the relationship."), (-30, "The first post."), (-10, "{V} blocks the first account."), (0, "{V} reports the posts.")],
        identified: "Screenshots and block records.",
        mood: .wantsConviction,
        impact: "I look over my shoulder at work. More than sixty posts in five weeks, with my job and my daily routine, and no name needed. I blocked the account twice, and a new one appeared. I changed my commute and told my manager. I just want it to stop.",
        genders: ["D": .male, "V": .female])

    static let formerEmployeeFiles = SmallCases.make(
        key: "story.formerEmployeeFiles",
        category: .cyber,
        headlines: ["Fired Employee Logs Into Company Server After Termination", "IT Manager Finds Deleted Project Folders"],
        law: "accessingComputers",
        threshold: 6,
        spec: "Willfully accessed the computers of {V}, a company, without authority, on {DATE}.",
        ages: 24...55,
        victim: true,
        summary: "{D} was fired on a Friday. On {DATE} the weekend logs showed {D.his} old credentials deleting three project folders from the company server. {DL} says {D.he} only logged in to retrieve personal photos and the deleted folders were already missing.",
        state: [E(.digital, 3, "Server Logs", "{D}'s credentials delete three folders at 9:12 p.m."), E(.document, 2, "Termination Letter", "{D} fired Friday with access revoked on paper.")],
        defense: [E(.statement, 1, "Personal Photos", "{DL} says {D.he} logged in for personal photos.")],
        role: "IT manager",
        exam: [.direct("What is your role at the company?", "\"I'm the IT manager. I administer the server, manage logins, and review the access logs for the whole company.\""), .direct("What happened with {D}'s employment?", "\"{D} was fired on a Friday. A termination letter was issued and, on paper, {D.his} access was to be revoked that day.\""), .direct("What did the weekend logs show?", "\"On {DATE}, {D.his} credentials logged in at 9:10 p.m. from a home connection. At 9:12 three project folders were deleted.\""), .direct("Why did the credentials still work?", "\"We hadn't finished disabling the account by the weekend. That was a gap on our side, and I take responsibility for it.\""), .direct("What was in those folders?", "\"Active project files for three clients, with months of work. We restored most of it from backup, but it took two days.\""), .direct("What did you do when you saw the logs?", "\"I printed them out the next morning and notified the owner. We changed every password and reviewed the whole server.\""), .cross("Isn't it true you did not disable the account before the weekend?", "\"That's correct. The account was still active, which is how anyone with those credentials could log in.\""), .cross("Could a scheduled cleanup job have deleted those folders?", "\"We do have an automated cleanup job. I'd have to review whether it flagged those folders, and I haven't confirmed it yet.\""), .cross("Do the logs show the person typing the delete command?", "\"They show the account and the connection. They don't show who sat at the keyboard.\""), .cross("Was anything else on the server touched?", "\"No. Only the three folders were affected. Nothing else was deleted or changed.\""), .cross("Did the defendant have personal photos on the company server?", "\"I'm not aware of it, but employees sometimes save a few. I haven't looked at {D.his} home folder.\"")],
        theory: ("{D} deleted company files.", "A man retrieving photos."),
        allocution: "\"I only logged in to retrieve my personal photos from the company server, and my login still worked after I was let go. Three project folders were already missing when I saw the list, and I didn't understand what had happened. I went straight to my pictures. I'm sorry that I touched the system at all.\"",
        truths: ("The deletion command was run from {DL}'s home address.", "The logs showed a scheduled cleanup job had already flagged the folders for deletion."),
        defendant: [.direct("Why did you log in on that weekend?", "\"I wanted to retrieve personal photos I'd saved to the company server. I'd been fired and didn't want to lose them.\""), .direct("Did you know your access was supposed to be revoked?", "\"The letter said it would be, but my login still worked. I assumed it was a short grace period.\""), .direct("What did you see when you logged in?", "\"Three project folders were already missing from the list. I didn't understand what had happened.\""), .direct("Did you delete anything?", "\"No. I went straight to my personal folder and copied the photos. I didn't touch any project folders.\""), .direct("Why did you log in at that hour?", "\"I got home late and it was the first quiet moment I had. I wasn't hiding it, and I used my own connection from home.\""), .direct("How do you feel about the accusation?", "\"Angry and hurt. I worked there for years, and I would never destroy work my coworkers did.\""), .cross("You were fired three days before, correct?", "\"Yes, on Friday. I was upset, but I wasn't plotting anything. I just wanted my photos.\""), .cross("The logs show a deletion command at 9:12, two minutes after your login?", "\"That's what I'm told. I don't know how it got there, and I know the timing looks bad.\""), .cross("You logged in from your home address?", "\"Yes. I wasn't trying to hide, and I used my own login.\""), .cross("You didn't ask IT for permission to retrieve photos?", "\"No. I figured they'd say no, and I thought it was just a few files. I should have asked.\""), .cross("You're sure the folders were already gone?", "\"I'm sure. They weren't in the list when I looked, and I'd have noticed.\"")],
        openings: ("{D} was fired on a Friday, and on {DATE} the logs show {D.his} old credentials logging in from home at 9:10 p.m. Two minutes later, three project folders were deleted, and the State will show who held those credentials.", "{D} logged in to rescue personal photos and found the folders already gone. The defense says the company never shut off the account and had an automated cleanup job that had flagged those folders."),
        closings: ("A fired employee, an account left open, a login from home, and a deletion two minutes later. The logs point to one person with a reason and the credentials to do it.", "The company left the account active, a cleanup job had flagged the folders, and the logs don't show who typed the command. The State cannot say beyond doubt that {D} deleted anything."),
        timeline: [(-3, "{DL} is fired."), (0, "9:10 p.m.: {DL} logs in from home."), (0, "9:12 p.m.: three folders are deleted."), (1, "The IT manager sees the logs.")],
        identified: "Server logs.",
        mood: .wantsConviction,
        impact: "Three weeks of work. Our project folders were deleted over a weekend, and rebuilding them cost our whole team. Clients waited and we lost one account. The logs showed an old login, and we had to review every credential in the company.",
        genders: ["D": .male])

    static let plannedPharmacyRobbery = SmallCases.make(
        key: "story.plannedPharmacyRobbery",
        category: .robbery,
        headlines: ["Two Men Plotted Pharmacy Robbery in Texts, Deputies Say", "Plan Fell Apart When Getaway Driver Talked"],
        law: "conspiracyRobbery",
        threshold: 7,
        spec: "Agreed with another person to commit robbery with a dangerous weapon at {V}, a pharmacy, on {DATE}.",
        ages: 19...40,
        victim: true,
        summary: "The night before {DATE}, {D} texted a friend about robbing a pharmacy at closing, listing a time, a pistol, and a stolen plate. The driver, picked up on an unrelated stop, told deputies about the plan. {DL} says the texts were a bad joke.",
        state: [E(.digital, 3, "Text Messages", "{D} writes about a pistol, a time, and a stolen plate."), E(.statement, 3, "Getaway Driver", "The driver describes the plan and {D}'s role.")],
        defense: [E(.statement, 1, "Joke", "{DL} says the messages were a bad joke.")],
        role: "Sheriff's detective",
        exam: [.direct("What do the texts say?", "\"The night before, {D} texted a friend about robbing a pharmacy at closing, listing a time, a pistol, and a stolen plate.\""), .direct("How did you learn about it?", "\"The driver named in the texts was picked up on an unrelated stop and told deputies about the plan.\""), .direct("Did a robbery happen?", "\"No. Nothing happened at the pharmacy. No one was hurt and nothing was taken.\""), .direct("How did you confirm the texts came from {D}'s phone?", "\"We got a warrant for the phone company's records, and the number and the account holder matched {DL}. The messages were sent late the night before.\""), .direct("What do the texts specifically list?", "\"A closing time, a pistol, and a stolen license plate, plus an instruction on where to park. They were sent the night before at about eleven.\""), .direct("What did you do after you read them?", "\"I contacted the pharmacy, set up extra patrols at closing, and applied for warrants for {D.his} phone and car. We saw no one at the pharmacy that evening.\""), .cross("No robbery occurred, did it?", "\"Correct. The pharmacy was never robbed, and no one showed up with a gun.\""), .cross("The driver got a lighter charge for talking, didn't the driver?", "\"The driver received consideration for cooperating, yes. That is common, and the jury can weigh it.\""), .cross("Could the texts have been a joke?", "\"They could be read that way. It is for the jury to decide, but the details were specific.\""), .cross("Did you find a stolen plate or pistol in the defendant's possession?", "\"Not at the time of the texts. We found nothing at the pharmacy, and the plate and pistol were not recovered until later, if at all.\""), .cross("What is the driver's own legal situation?", "\"The driver was facing charges on the traffic stop and was offered consideration for cooperating. I can't say how much that colored what was told to us.\"")],
        defenseRole: "Pharmacy manager",
        defenseExam: [.direct("Did you see {D} around the pharmacy?", "\"I saw {D} near closing the night before, in the parking lot. It was a brief sighting.\""), .direct("What did the defendant do?", "\"{D.He} stood near a car and looked around. Then {D.he} drove off.\""), .direct("Did that seem unusual to you?", "\"A bit, but a lot of people park there. I noticed only because I was locking up.\""), .direct("What is your role at the pharmacy, and what is your closing routine?", "\"I'm the pharmacy manager. We close at nine, count the register, and lock the controlled-substance cabinet before the last person leaves.\""), .direct("What did you notice outside the evening before?", "\"A car parked across the lot with someone in it for about fifteen minutes. I thought it was odd, but I didn't call anyone.\""), .direct("Did anything happen at closing that night?", "\"No. We closed and left without any problem, and nobody came in with a weapon or made a threat.\""), .cross("Did the defendant come into the pharmacy?", "\"No. {D.He} never came in.\""), .cross("Did you see a weapon?", "\"No. I did not see any weapon on {DF} or in the car.\""), .cross("Did the defendant return the next night?", "\"No. I did not see {D.him} again, and nothing happened that night either.\""), .cross("Did you know the defendant?", "\"No. I'd never seen {DF} before and I only recognized {DF} later when deputies showed me a photo.\""), .cross("Did you take any extra precautions after deputies told you?", "\"Yes. We had two staff close for a week and the sheriff's office had a car nearby. Nothing happened.\"")],
        theory: ("{D} agreed to rob a pharmacy.", "A joke text."),
        allocution: "\"Those texts were a bad joke between friends. I was trying to sound tough after a heist movie, and I did not think anyone would read it seriously. I never planned to rob anyone. I was driving around that night and never went inside. I'm sorry to the pharmacy, and I'll never write anything like that again.\"",
        truths: ("A pistol and a stolen plate were in {DL}'s trunk.", "The driver admitted inventing the time to help the driver's own case."),
        defendant: [.direct("Did you plan to rob that pharmacy?", "\"No. I never planned a robbery. The texts were a bad joke between friends.\""), .direct("Why did you write those texts?", "\"It was a stupid joke. I was trying to sound tough to a friend, and I did not think anyone would take it seriously.\""), .direct("Why were you near the pharmacy?", "\"I was driving around. I did not go in, and I never meant to hurt anyone.\""), .direct("Why did you send those texts?", "\"It was a joke with a friend. We'd been watching a heist movie and I wrote out a plan in the same style to mess with them.\""), .direct("Where were you the evening after the texts?", "\"Driving around. I went by the pharmacy because it's on my way home, but I never parked or got out.\""), .direct("What did you think when deputies contacted you?", "\"I was shocked. I told them it was a joke and showed them the movie I'd been talking about.\""), .cross("You listed a pistol, a time, and a plate. That's a lot of detail for a joke, isn't it?", "\"It was a joke, and I made it sound real. I know now how that looks.\""), .cross("A pistol was in your trunk, wasn't it?", "\"I keep a pistol for my safety. It was not for a pharmacy.\""), .cross("Why would you have a stolen plate?", "\"I found it. I never put it on a car, and I did not think about what it meant.\""), .cross("A time, a pistol, and a stolen plate. Why add all that detail to a joke?", "\"That's how the movie went. I know it sounds bad now, and I should have never written it.\""), .cross("Your friend didn't treat it as a joke. Why would the driver bring it to deputies?", "\"I don't know. The driver was in trouble and was probably looking for something to offer.\"")],
        openings: ("The night before, {D} texted a friend about robbing a pharmacy at closing, listing a time, a pistol, and a stolen plate. The driver told deputies about the plan, and the State will show why that matters.", "The defense evidence includes a bad joke between friends, a driver with a deal, and a pharmacy that was never touched. No robbery ever occurred."),
        closings: ("A time, a pistol, a stolen plate, and a driver who agreed to talk. This was a plan, and what stopped it was the driver, not {D}.", "The pharmacy was never robbed. A driver with a deal tells you what the State needs to hear, and a tasteless text is not a crime. Nothing was done."),
        timeline: [(-1, "{DL} texts the plan."), (-1, "{DL} stages near the pharmacy."), (0, "The driver is stopped on another matter."), (1, "A detective reads the texts.")],
        identified: "Text messages and a driver's account.",
        aggravating: ["The offense involved a firearm"],
        mood: .divided,
        doctrines: ["burdenOfProof", "hearsay"],
        genders: ["D": .male])

    static let toddlerLeftHome = SmallCases.make(
        key: "story.toddlerLeftHome",
        category: .family,
        headlines: ["Toddler Found Alone in Apartment While Mother Worked Late Shift", "Neighbor Hears Crying, Calls Deputies"],
        law: "childAbuseMisd",
        threshold: 5,
        spec: "Allowed a three-year-old child in {D.his} care to be left without proper care or supervision, on {DATE}.",
        ages: 19...40,
        victim: false,
        summary: "A neighbor heard a child crying for an hour on {DATE} and called deputies. Deputies found {D}'s three-year-old alone, unharmed, in the apartment at 11 p.m. {D.He} was at work until midnight. {DL} says a sitter was supposed to come and did not.",
        state: [E(.statement, 3, "Neighbor", "The child cried alone for an hour."), E(.document, 2, "Work Schedule", "{D} scheduled until midnight.")],
        defense: [E(.statement, 1, "Sitter", "{DL} says a sitter was supposed to come.")],
        role: "Sheriff's deputy",
        exam: [.direct("How were you called to the apartment?", "\"A neighbor called after hearing a child crying for about an hour. I arrived and found a three-year-old alone in the apartment at 11 p.m.\""), .direct("What condition was the child in?", "\"Crying, but not hurt. The child had no injuries. I stayed until a relative could take the child.\""), .direct("Where was {D}?", "\"At work. {D} was due to finish at midnight, and I spoke with {D.him} after the shift.\""), .direct("What did you find when you entered the apartment?", "\"A three-year-old in the middle of the living room, tearful but unhurt, with a half-eaten snack and a tablet on the couch. No adult was inside.\""), .direct("How did you get in?", "\"A neighbor let us into the building and the apartment door was unlocked. We announced ourselves and called out before going in.\""), .direct("How did you reach the defendant?", "\"We got the number from the lease and called. {D.He} said {D.he} was at work and answered quickly, and {D.he} told me a sitter was supposed to come.\""), .cross("{D} told you a sitter was supposed to come, didn't {D.he}?", "\"Yes. That was the explanation. I did not speak to the sitter that night.\""), .cross("The apartment was safe, wasn't it?", "\"Mostly. There was nothing dangerous within the child's reach that I noticed, but it is still a three-year-old alone.\""), .cross("Did the defendant cooperate?", "\"Yes. {D.He} was upset and cooperative, and answered my questions.\""), .cross("Were there any hazards in the apartment, such as open windows or exposed outlets?", "\"Nothing I noted. The windows were closed and the stove was off. It was a tidy apartment.\""), .cross("How long was the child alone, as far as you can tell?", "\"The neighbor reported crying for about an hour. I can't say when {D.he} left, but the work schedule shows six o'clock.\"")],
        theory: ("{D} left a toddler alone.", "A sitter who did not come."),
        allocution: "\"I did not think I was leaving my child alone. A sitter had agreed weeks earlier, and I believed she was coming. I was at work and could not step away, and I assumed things were fine. I came straight home and held my child. I'm so sorry, and I haven't left my child alone since.\"",
        truths: ("{DL} never texted the sitter that day.", "The sitter says she was asked weeks earlier."),
        defendant: [.direct("Did you leave your child alone?", "\"I did not think I was leaving my child alone. A sitter was supposed to come, and I believed the sitter did.\""), .direct("Why didn't you check?", "\"I was at work and could not step away. I assumed things were fine, because the sitter had agreed.\""), .direct("How did you feel when you learned?", "\"I was terrified. I came straight home and held my child. I have not left my child alone since.\""), .direct("Tell the jury what arrangements you had made for the child that night.", "\"A sitter had agreed weeks earlier to watch my child on Fridays when I worked late. The sitter had never missed one before.\""), .direct("When did you leave for work?", "\"A little before six. I told my child I'd be back late and that the sitter was on the way.\""), .direct("What did you do when you got the call?", "\"I was at the register and couldn't answer at first. I called back as soon as I could, then left work and drove straight home.\""), .cross("You never texted the sitter that day, did you?", "\"No. I was busy and I did not check. I should have confirmed.\""), .cross("The child cried for an hour. Didn't you see it?", "\"I did not know. I was not home and had no camera.\""), .cross("You could have called someone else that night, couldn't you?", "\"Yes, and I did not think of it. I trusted the sitter, and I was wrong.\""), .cross("Who was supposed to confirm the arrangement?", "\"I was. The sitter relied on me to text, and I assumed the usual arrangement still held.\""), .cross("Your child cried for an hour. Who was watching?", "\"No one, and I live with that. I thought the sitter was coming, and I would never knowingly leave my child alone.\"")],
        openings: ("A neighbor heard a child crying for an hour and called deputies. They found {D}'s three-year-old alone in an apartment at 11 p.m., while {DL} was at work until midnight.", "The defense will point you to a sitter who was supposed to come and did not, and a worried parent who was not told. The child was unharmed."),
        closings: ("A three-year-old, alone, crying for an hour, with a parent at work for another hour. No sitter was confirmed, and no one was watching that child.", "{D} believed a sitter was coming, and that belief was reasonable. A last-minute failure by someone else is a tragedy of luck, not a crime of neglect."),
        timeline: [(0, "6 p.m.: {DL} leaves for work."), (0, "10 p.m.: the child begins to cry."), (0, "11 p.m.: deputies enter."), (1, "12 a.m.: {DL} gets off work.")],
        identified: "A neighbor's call.",
        mood: .sympathetic,
        genders: ["D": .female])

    static let partyGrab = SmallCases.make(
        key: "story.partyGrab",
        category: .family,
        headlines: ["Woman Says Boyfriend Grabbed and Shoved Her at House Party", "Guests Witness Argument Turn Physical"],
        law: "assaultFemale",
        spec: "Assaulted {V}, a female, being a male over eighteen years of age, on {DATE}.",
        ages: 20...50,
        victim: true,
        summary: "At a house party on {DATE}, {D} grabbed {V}, {D.his} girlfriend, by the arm and shoved {V.him} into a wall during an argument. Two guests saw it. {V} had a bruised arm. {DL} says {V} slipped.",
        state: [E(.statement, 3, "Guest", "{D} grabbed {V} and shoved {V.him}."), E(.forensic, 2, "Photos", "Finger-shaped bruises on {V}'s upper arm.")],
        defense: [E(.statement, 1, "Slipped", "{DL} says {V} slipped.")],
        role: "Victim",
        exam: [.direct("Tell us what happened at the house party.", "\"We were arguing about something. {D} grabbed my arm and shoved me into a wall. It happened fast, and I was shocked.\""), .direct("Were you hurt?", "\"I had a bruise on my arm, where {D.he} grabbed me. It was sore for days.\""), .direct("Who saw it?", "\"Two guests saw it. They both came over right away to see if I was okay.\""), .direct("How did the argument start?", "\"It began over a text {DL} saw on my phone. We were both upset and we moved from the kitchen into the hallway where the music was quieter.\""), .direct("Describe what {D} did with {D.his} hands.", "\"{D.He} took hold of my upper arm hard, pulled me toward the wall, and pushed me into it. My back hit the plaster.\""), .direct("What did you do right afterward?", "\"I pulled away and went to the bathroom. A friend came in and told me to call someone, and deputies came about thirty minutes later.\""), .cross("You had been drinking that night, hadn't you?", "\"I had one drink. I was not drunk, and I knew exactly what was happening.\""), .cross("The floor was wet that night, wasn't it?", "\"Not where I was standing. I know where I fell, and it was dry.\""), .cross("Isn't it possible that you slipped and the defendant tried to catch you?", "\"No. I felt the shove. I know the difference between slipping and being pushed.\""), .cross("Was the hallway crowded at that moment?", "\"There were a few people near the end of the hall, and the music was loud. Two of them saw it, and I don't think anyone else was looking.\""), .cross("Did you tell the deputies right away that the defendant had shoved you?", "\"Yes. I said it as soon as they came in, and I showed them my arm where it was already turning purple.\"")],
        theory: ("{D} shoved {V.his} girlfriend.", "A slip."),
        allocution: "\"We were arguing at that party, and {V} slipped, and I tried to catch {V.him} by the arm. That is how the bruise happened. It was a bad argument, and I never meant it to go as it did. I'm sorry for the mark on {V.his} arm and for the scene in front of friends.\"",
        truths: ("The bruises matched {DL}'s hand.", "The floor was dry."),
        defendant: [.direct("Did you shove {V}?", "\"No. I did not shove {V.him}. We were arguing, and {V} slipped.\""), .direct("What did you do when {V} slipped?", "\"I tried to catch {V.him}, and I grabbed {V.his} arm. That is how the bruise happened.\""), .direct("Did you mean to hurt {V}?", "\"Never. I would never do that. It was a bad argument, and it was an accident.\""), .direct("How long had you and {V} been together?", "\"About a year. We lived apart but spent most nights together, and we'd had a couple of arguments before but never anything physical.\""), .direct("What happened in the hallway?", "\"We were raising our voices. {V} stepped back, slipped on something, and I reached for {V.his} arm to keep {V.him} from falling.\""), .direct("What did you do afterward?", "\"I helped {V.him} up and asked if {V.he} was okay. {V} pulled away and went to the bathroom, and I stayed out in the hall.\""), .cross("Two guests say they saw a shove. Are they lying?", "\"They misjudged. It was crowded and it happened fast. I understand why they thought so.\""), .cross("The bruise matches a hand on the arm. How do you explain that?", "\"It does match a hand. It was mine, because I was trying to stop the fall.\""), .cross("You and {V} were fighting that night, weren't you?", "\"We were arguing. It was loud, but it was not physical until {V} slipped.\""), .cross("Where were the two guests standing?", "\"At the end of the hall by the kitchen. They had a view of the doorway but not the whole room.\""), .cross("The bruises match the shape of a hand. Whose hand was it?", "\"Mine, because I grabbed {V.his} arm. I'm not saying I didn't touch {V.him}. I'm saying I didn't shove {V.him}.\"")],
        openings: ("At a house party, {D} grabbed {V}, a partner, by the arm and shoved {V.him} into a wall during an argument. Two guests saw it, and {V} had a bruised arm.", "The defense witnesses will explain that {V} slipped and that {D} grabbed an arm to catch {V.him}. Two guests misjudged a fast moment."),
        closings: ("Two guests saw the shove, and {V} had a bruise shaped like a hand. A person who grabs and shoves a partner into a wall has committed an assault.", "A bruise from a catching hand and a floor where someone slipped. The State's witnesses saw a moment, not an intent, and without intent there is no assault."),
        timeline: [(0, "10:20 p.m.: the argument."), (0, "10:25 p.m.: the shove."), (0, "11 p.m.: deputies arrive.")],
        identified: "Two guests and photos.",
        aggravating: ["The offense involved a victim in a domestic relationship"],
        mood: .wantsConviction,
        genders: ["D": .male, "V": .female])

    static let roadRageBat = SmallCases.make(
        key: "story.roadRageBat",
        category: .violent,
        headlines: ["Driver Gets Out With Baseball Bat After Highway Cut-Off", "Rear Window Shattered at Red Light"],
        law: "awdw",
        threshold: 6,
        spec: "Assaulted {V} with a deadly weapon, a baseball bat, on {DATE}.",
        ages: 21...55,
        victim: true,
        summary: "After {V} cut in front of {D} on {DATE}, {DL} followed {V} to a red light, got out with a baseball bat, and smashed {V}'s rear window. {V} was cut on the neck by glass. {DL} says {V} slammed the brakes and {D.he} only swung at the car.",
        state: [E(.video, 3, "Dash Camera", "A man with a bat swings at {V}'s rear window."), E(.forensic, 2, "Medical Records", "Glass cuts on {V}'s neck.")],
        defense: [E(.statement, 1, "Swing at Car", "{DL} says {D.he} swung only at the car.")],
        role: "Driver",
        exam: [.direct("What happened on the road that day?", "\"After I merged in front of {D}, {D.he} followed me to a red light, got out with a baseball bat, and smashed my rear window.\""), .direct("What was hit?", "\"The rear window of my car. Glass sprayed into the car, and I was cut on the neck.\""), .direct("How far did {D} follow you?", "\"About three miles. {D.He} stayed right behind me the whole way, and I knew something was wrong.\""), .direct("How did the encounter start?", "\"I changed lanes in heavy traffic at about 5:40 and a truck behind me leaned on the horn. The driver stayed on my bumper for three miles.\""), .direct("What did you see when you stopped at the light?", "\"The truck pulled in behind me, and a person got out with a baseball bat and walked up to my rear window. I had a few seconds to duck.\""), .direct("What injuries did you have?", "\"Glass cut the back of my neck and one shoulder. I got stitches at urgent care and have a scar.\""), .cross("{D} says you braked suddenly. Did you?", "\"I stopped short at the light. I did not slam the brakes to cause anything.\""), .cross("{D} never touched you with the bat, did {D.he}?", "\"No. The glass did the damage. {D.He} hit the window, and I was near it.\""), .cross("Did you cut in front of the defendant?", "\"I changed lanes and may have been close. I did not mean to cut anyone off.\""), .cross("Did you brake hard at the light?", "\"I stopped as the light turned red. I might have braked harder than usual, but I didn't slam the brakes on purpose.\""), .cross("Did you make any gestures or remarks to the defendant?", "\"I may have waved my hand to apologize for cutting in, but I didn't say anything or do anything aggressive.\"")],
        theory: ("{D} attacked a car with a bat.", "A swing at property."),
        allocution: "\"I swung at the car, not at the driver. A car cut in front of me, and the driver slammed the brakes, and I almost hit it. I was angry, and I grabbed a bat from my truck. I'm sorry that glass cut {V.him}, and I'll pay for every cost.\"",
        truths: ("The swing came within a foot of {V}'s head.", "A third car's dash camera showed {V} braking hard twice before the light."),
        defendant: [.direct("Did you swing the bat?", "\"I swung at the car. I did not swing at the driver. I was angry, and I hit the rear window.\""), .direct("Why were you so angry?", "\"The other driver slammed the brakes right in front of me, and I almost hit the car. I was scared and furious.\""), .direct("Why did you get out of the truck with a bat?", "\"The bat was in my truck, and I grabbed it. I wanted to talk, and I did not think about how that would look.\""), .direct("What happened on the road before the stoplight?", "\"A car cut in front of me and then braked hard. I had to stand on my own brakes to avoid hitting it.\""), .direct("Why did you follow {V} for three miles?", "\"I wanted to say something about the way {V.he} had been driving. I wasn't thinking clearly, and I stayed behind the car without really deciding what to do.\""), .direct("What were you thinking when you got out with the bat?", "\"Nothing sensible. I was angry, and the bat was in my truck bed because I'd been at a softball practice.\""), .cross("You followed {V} for three miles, didn't you?", "\"Yes. I wanted to talk, and I stayed behind. I should have let it go.\""), .cross("You smashed a window with a baseball bat. That's not talking, is it?", "\"No. I lost my temper for a second. I regret it, and I did not mean to hurt anyone.\""), .cross("{V} was cut on the neck. Aren't you responsible for that?", "\"I am responsible for the window. I did not intend the cut. But I know it came from what I did.\""), .cross("You swung a baseball bat at a window with a person sitting behind it. How can you say you only swung at the car?", "\"I aimed at the glass, not at {V}. It broke more than I expected and it cut {V.him}, and I'm very sorry for that.\""), .cross("A third driver's dash camera shows you tailgating before the light. Are you denying that?", "\"No. I was close to the bumper. I was frustrated, and I didn't keep a safe distance.\"")],
        openings: ("After a lane change, {D} followed {V} for three miles, got out of a truck with a baseball bat at a red light, and smashed {V}'s rear window, cutting {V.him} with glass.", "Listen for the defense evidence, which will show that {V} braked hard in front of {D}. {DL} swung at a car, not a person, and never meant to hurt anyone."),
        closings: ("Three miles, a baseball bat, and a smashed window with a driver inside who was cut by glass. That is what road rage looks like, and {D} did it.", "A driver braked hard, and another lost control for a moment. {D} swung at a car and never touched a person. That is property damage, not an attack on a driver."),
        timeline: [(0, "5:40 p.m.: the cut-off."), (0, "5:50 p.m.: {DL} follows to a red light."), (0, "5:52 p.m.: the swing."), (0, "6:10 p.m.: deputies arrive.")],
        identified: "A dash camera.",
        aggravating: ["The defendant was armed with a deadly weapon at the time of the crime"],
        mood: .wantsConviction,
        impact: "I couldn't drive for a month. Someone with a bat came to my window at a red light and smashed my back glass, and a shard cut my neck. I sat frozen with my hands on the wheel. I drive with the doors locked now and I watch my mirrors.",
        genders: ["D": .male, "V": .male])

    static let fourthDwi = SmallCases.make(
        key: "story.fourthDwi",
        category: .traffic,
        headlines: ["Driver With Three Prior DWIs Stopped After Weaving", "Habitual Impaired Driving Charge After Late-Night Stop"],
        law: "habitualDWI",
        threshold: 7,
        spec: "Drove while impaired, having been convicted of three prior impaired-driving offenses within ten years, on {DATE}.",
        ages: 28...62,
        victim: false,
        summary: "A trooper saw {D}'s car weave across the center line on {DATE}. {D.He} smelled of alcohol and blew 0.12. A records check showed three prior DWI convictions in the last ten years. {DL} says {D.he} had one drink and was driving carefully.",
        state: [E(.forensic, 3, "Breath Test", "0.12 at the station."), E(.document, 3, "Prior Convictions", "Three impaired-driving convictions within ten years.")],
        defense: [E(.statement, 1, "One Drink", "{DL} says {D.he} had one drink.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("What did you see on {DATE}?", "\"At about 10:30 p.m. I watched {D}'s car weave across the center line on the highway. I followed and then pulled it over.\""), .direct("What did you notice at the window?", "\"A strong smell of alcohol and bloodshot eyes. {D.He} was fumbling with the license and slow to answer questions.\""), .direct("What did {D} say about drinking?", "\"{D.He} said one drink and that {D.he} had left a bar thirty minutes earlier. {D.He} said {D.he} was driving carefully.\""), .direct("What did the breath test show?", "\"A 0.12 at the station, around midnight. The test was conducted by a certified operator on the department's instrument.\""), .direct("What did your records check show?", "\"Three prior impaired-driving convictions within the past ten years. That elevates this offense to a more serious level.\""), .direct("How many times did the car cross the line?", "\"Twice in the quarter mile I followed. It drifted over by about half a car width each time and then corrected.\""), .cross("Isn't it true the breath test was ninety minutes after the stop?", "\"Yes, about that. Processing takes time, and I followed the standard observation period before the test.\""), .cross("Did the defendant fail field sobriety tests?", "\"I conducted a few and made notes. {D.He} had some trouble, but I wouldn't call it a complete failure.\""), .cross("Did you find open containers in the car?", "\"No. I found no bottles or cans in the vehicle.\""), .cross("Did the defendant argue or resist?", "\"No. {D.He} was cooperative and polite throughout the stop and at the station.\""), .cross("Did you speak to the bar about what the defendant drank?", "\"I didn't. I took {D.his} word on the timing and relied on the breath result.\"")],
        theory: ("{D} drove drunk a fourth time.", "One drink."),
        allocution: "\"I was at a bar for a couple of hours, and I had one drink, a soda, and a sandwich. A truck passed me at a bend in the road, and I may have drifted a bit when I corrected. I believe I was driving carefully. I know my record, and I'm sorry that it looks the way it does.\"",
